/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][12]=[{"key":"cf:241","law":"cf","ref":"241","label":"Constituição Federal · CF/88 · Art. 241","paragraphs":["Art. 241. A União, os Estados, o Distrito Federal e os Municípios disciplinarão por meio de lei os consórcios públicos e os convênios de cooperação entre os entes federados, autorizando a gestão associada de serviços públicos, bem como a transferência total ou parcial de encargos, serviços, pessoal e bens essenciais à continuidade dos serviços transferidos. (Artigo com redação dada pela Emenda Constitucional nº 19, de 1998)"],"url":""},{"key":"l9637:1","law":"l9637","ref":"1","label":"Lei 9.637/1998 · Art. 1","paragraphs":["Art. 1º O Poder Executivo poderá qualificar como organizações sociais pessoas jurídicas de direito privado, sem fins lucrativos, cujas atividades sejam dirigidas ao ensino, à pesquisa científica, ao desenvolvimento tecnológico, à proteção e preservação do meio ambiente, à cultura e à saúde, atendidos aos requisitos previstos nesta Lei."],"url":""},{"key":"l9637:2","law":"l9637","ref":"2","label":"Lei 9.637/1998 · Art. 2","paragraphs":["Art. 2º São requisitos específicos para que as entidades privadas referidas no artigo anterior habilitem-se à qualificação como organização social:","I - comprovar o registro de seu ato constitutivo, dispondo sobre:","a) natureza social de seus objetivos relativos à respectiva área de atuação;","b) finalidade não-lucrativa, com a obrigatoriedade de investimento de seus excedentes financeiros no desenvolvimento das próprias atividades;","c) previsão expressa de a entidade ter, como órgãos de deliberação superior e de direção, um conselho de administração e uma diretoria definidos nos termos do estatuto, asseguradas àquele composição e atribuições normativas e de controle básicas previstas nesta Lei;","d) previsão de participação, no órgão colegiado de deliberação superior, de representantes do Poder Público e de membros da comunidade, de notória capacidade profissional e idoneidade moral;","e) composição e atribuições da diretoria;","f) obrigatoriedade de publicação anual, no Diário Oficial da União, dos relatórios financeiros e do relatório de execução do contrato de gestão;","g) no caso de associação civil, a aceitação de novos associados, na forma do estatuto;","h) proibição de distribuição de bens ou de parcela do patrimônio líquido em qualquer hipótese, inclusive em razão de desligamento, retirada ou falecimento de associado ou membro da entidade;","i) previsão de incorporação integral do patrimônio, dos legados ou das doações que lhe foram destinados, bem como dos excedentes financeiros decorrentes de suas atividades, em caso de extinção ou desqualificação, ao patrimônio de outra organização social qualificada no âmbito da União, da mesma área de atuação, ou ao patrimônio da União, dos Estados, do Distrito Federal ou dos Municípios, na proporção dos recursos e bens por estes alocados;","II - haver aprovação, quanto à conveniência e oportunidade de sua qualificação como organização social, do Ministro ou titular de órgão supervisor ou regulador da área de atividade correspondente ao seu objeto social e do Ministro de Estado da Administração Federal e Reforma do Estado."],"url":""},{"key":"cf:37","law":"cf","ref":"37","label":"Constituição Federal · CF/88 · Art. 37","paragraphs":["Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte: (“Caput” do artigo com redação dada pela Emenda Constitucional nº 19, de 1998)","I - os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","II - a investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","III - o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;","IV - durante o prazo improrrogável previsto no edital de convocação, aquele aprovado em concurso público de provas ou de provas e títulos será convocado com prioridade sobre novos concursados para assumir cargo ou emprego, na carreira;","V - as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei, destinam-se apenas às atribuições de direção, chefia e assessoramento; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VI - é garantido ao servidor público civil o direito à livre associação sindical;","VII - o direito de greve será exercido nos termos e nos limites definidos em lei específica; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VIII - a lei reservará percentual dos cargos e empregos públicos para as pessoas portadoras de deficiência e definirá os critérios de sua admissão;","IX - a lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","X - a remuneração dos servidores públicos e o subsídio de que trata o § 4º do art. 39 somente poderão ser fixados ou alterados por lei específica, observada a iniciativa privativa em cada caso, assegurada revisão geral anual, sempre na mesma data e sem distinção de índices; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XI - a remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos da administração direta, autárquica e fundacional, dos membros de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, dos detentores de mandato eletivo e dos demais agentes políticos e os proventos, pensões ou outra espécie remuneratória, percebidos cumulativamente ou não, incluídas as vantagens pessoais ou de qualquer outra natureza, não poderão exceder o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, aplicando-se como limite, nos Municípios, o subsídio do Prefeito, e nos Estados e no Distrito Federal, o subsídio mensal do Governador no âmbito do Poder Executivo, o subsídio dos Deputados Estaduais e Distritais no âmbito do Poder Legislativo e o subsídio dos Desembargadores do Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, no âmbito do Poder Judiciário, aplicável este limite aos membros do Ministério Público, aos Procuradores e aos Defensores Públicos; (Inciso com redação dada pela Emenda Constitucional nº 41, de 2003)","XII - os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não poderão ser superiores aos pagos pelo Poder Executivo;","XIII - é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XIV - os acréscimos pecuniários percebidos por servidor público não serão computados nem acumulados para fins de concessão de acréscimos ulteriores; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XV - o subsídio e os vencimentos dos ocupantes de cargos e empregos públicos são irredutíveis, ressalvado o disposto nos incisos XI e XIV deste artigo e nos arts. 39, § 4º, 150, II, 153, III, e 153, § 2º, I; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVI - é vedada a acumulação remunerada de cargos públicos, exceto, quando houver compatibilidade de horários, observado em qualquer caso o disposto no inciso XI: (“Caput” do inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","a) a de dois cargos de professor;","b) a de um cargo de professor com outro de qualquer natureza; (Alínea com redação dada pela Emenda Constitucional nº 138, de 2025)","c) a de dois cargos ou empregos privativos de profissionais de saúde, com profissões regulamentadas; (Alínea com redação dada pela Emenda Constitucional nº 34, de 2001)","XVII - a proibição de acumular estende-se a empregos e funções e abrange autarquias, fundações, empresas públicas, sociedades de economia mista, suas subsidiárias, e sociedades controladas, direta ou indiretamente, pelo poder público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVIII - a administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei;","XIX - somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação, cabendo à lei complementar, neste último caso, definir as áreas de sua atuação; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XX - depende de autorização legislativa, em cada caso, a criação de subsidiárias das entidades mencionadas no inciso anterior, assim como a participação de qualquer delas em empresa privada;","XXI - ressalvados os casos especificados na legislação, as obras, serviços, compras e alienações serão contratados mediante processo de licitação pública que assegure igualdade de condições a todos os concorrentes, com cláusulas que estabeleçam obrigações de pagamento, mantidas as condições efetivas da proposta, nos termos da lei, o qual somente permitirá as exigências de qualificação técnica e econômica indispensáveis à garantia do cumprimento das obrigações.","XXII - as administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio. (Inciso acrescido pela Emenda Constitucional nº 42, de 2003)","§ 1º A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.","§ 2º A não-observância do disposto nos incisos II e III implicará a nulidade do ato e a punição da autoridade responsável, nos termos da lei.","§ 3º A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:","I - as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços;","II - o acesso dos usuários a registros administrativos e a informações sobre atos de governo, observado o disposto no art. 5º, X e XXXIII;","III - a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública. (Parágrafo com redação dada pela Emenda Constitucional nº 19, de 1998)","§ 4º Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","§ 5º A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas as respectivas ações de ressarcimento.","§ 6º As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.","§ 7º A lei disporá sobre os requisitos e as restrições ao ocupante de cargo ou emprego da administração direta e indireta que possibilite o acesso a informações privilegiadas. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 8º A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato, a ser firmado entre seus administradores e o poder público, que tenha por objeto a fixação de metas de desempenho para o órgão ou entidade, cabendo à lei dispor sobre:","I - o prazo de duração do contrato;","II - os controles e critérios de avaliação de desempenho, direitos, obrigações e responsabilidade dos dirigentes;","III - a remuneração do pessoal. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 9º O disposto no inciso XI aplica-se às empresas públicas e às sociedades de economia mista, e suas subsidiárias, que receberem recursos da União, dos Estados, do Distrito Federal ou dos Municípios para pagamento de despesas de pessoal ou de custeio em geral. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 10. É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 ou dos arts. 42 e 142 com a remuneração de cargo, emprego ou função pública, ressalvados os cargos acumuláveis na forma desta Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração. (Parágrafo acrescido pela Emenda Constitucional nº 20, de 1998)","§ 11. Não serão computadas, para efeito dos limites remuneratórios de que trata o inciso XI do caput deste artigo, as parcelas de caráter indenizatório expressamente previstas em lei ordinária, aprovada pelo Congresso Nacional, de caráter nacional, aplicada a todos os Poderes e órgãos constitucionalmente autônomos. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005, e com redação dada pela Emenda Constitucional nº 135, de 2024)","§ 12. Para os fins do disposto no inciso XI do caput deste artigo, fica facultado aos Estados e ao Distrito Federal fixar, em seu âmbito, mediante emenda às respectivas Constituições e Lei Orgânica, como limite único, o subsídio mensal dos Desembargadores do respectivo Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal dos Ministros do Supremo Tribunal Federal, não se aplicando o disposto neste parágrafo aos subsídios dos Deputados Estaduais e Distritais e dos Vereadores. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005)","§ 13. O servidor público titular de cargo efetivo poderá ser readaptado para exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, enquanto permanecer nesta condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino, mantida a remuneração do cargo de origem. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 14. A aposentadoria concedida com a utilização de tempo de contribuição decorrente de cargo, emprego ou função pública, inclusive do Regime Geral de Previdência Social, acarretará o rompimento do vínculo que gerou o referido tempo de contribuição. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 15. É vedada a complementação de aposentadorias de servidores públicos e de pensões por morte a seus dependentes que não seja decorrente do disposto nos §§ 14 a 16 do art. 40 ou que não seja prevista em lei que extinga regime próprio de previdência social. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 16. Os órgãos e entidades da administração pública, individual ou conjuntamente, devem realizar avaliação das políticas públicas, inclusive com divulgação do objeto a ser avaliado e dos resultados alcançados, na forma da lei. (Parágrafo acrescido pela Emenda Constitucional nº 109, de 2021)","§ 17. (Vide Emenda Constitucional nº 132, de 2023)","§ 18. (Vide Emenda Constitucional nº 132, de 2023)"],"url":""},{"key":"l9637:5","law":"l9637","ref":"5","label":"Lei 9.637/1998 · Art. 5","paragraphs":["Art. 5º Para os efeitos desta Lei, entende-se por contrato de gestão o instrumento firmado entre o Poder Público e a entidade qualificada como organização social, com vistas à formação de parceria entre as partes para fomento e execução de atividades relativas às áreas relacionadas no art. 1º."],"url":""},{"key":"l9637:6","law":"l9637","ref":"6","label":"Lei 9.637/1998 · Art. 6","paragraphs":["Art. 6º O contrato de gestão, elaborado de comum acordo entre o órgão ou entidade supervisora e a organização social, discriminará as atribuições, responsabilidades e obrigações do Poder Público e da organização social.","Parágrafo único. O contrato de gestão deve ser submetido, após aprovação pelo Conselho de Administração da entidade, ao Ministro de Estado ou autoridade supervisora da área correspondente à atividade fomentada."],"url":""},{"key":"l9637:7","law":"l9637","ref":"7","label":"Lei 9.637/1998 · Art. 7","paragraphs":["Art. 7º Na elaboração do contrato de gestão, devem ser observados os princípios da legalidade, impessoalidade, moralidade, publicidade, economicidade e, também, os seguintes preceitos:","I - especificação do programa de trabalho proposto pela organização social, a estipulação das metas a serem atingidas e os respectivos prazos de execução, bem como previsão expressa dos critérios objetivos de avaliação de desempenho a serem utilizados, mediante indicadores de qualidade e produtividade;","II - a estipulação dos limites e critérios para despesa com remuneração e vantagens de qualquer natureza a serem percebidas pelos dirigentes e empregados das organizações sociais, no exercício de suas funções.","Parágrafo único. Os Ministros de Estado ou autoridades supervisoras da área de atuação da entidade devem definir as demais cláusulas dos contratos de gestão de que sejam signatários."],"url":""},{"key":"l9637:14","law":"l9637","ref":"14","label":"Lei 9.637/1998 · Art. 14","paragraphs":["Art. 14. É facultado ao Poder Executivo a cessão especial de servidor para as organizações sociais, com ônus para a origem.","§ 1º Não será incorporada aos vencimentos ou à remuneração de origem do servidor cedido qualquer vantagem pecuniária que vier a ser paga pela organização social.","§ 2º Não será permitido o pagamento de vantagem pecuniária permanente por organização social a servidor cedido com recursos provenientes do contrato de gestão, ressalvada a hipótese de adicional relativo ao exercício de função temporária de direção e assessoria.","§ 3º O servidor cedido perceberá as vantagens do cargo a que fizer juz no órgão de origem, quando ocupante de cargo de primeiro ou de segundo escalão na organização social."],"url":""},{"key":"l9637:17","law":"l9637","ref":"17","label":"Lei 9.637/1998 · Art. 17","paragraphs":["Art. 17. A organização social fará publicar, no prazo máximo de noventa dias contado da assinatura do contrato de gestão, regulamento próprio contendo os procedimentos que adotará para a contratação de obras e serviços, bem como para compras com emprego de recursos provenientes do Poder Público."],"url":""},{"key":"l9790:3","law":"l9790","ref":"3","label":"Lei 9.790/1999 · Art. 3","paragraphs":["Art. 3º A qualificação instituída por esta Lei, observado em qualquer caso, o princípio da universalização dos serviços, no respectivo âmbito de atuação das Organizações, somente será conferida às pessoas jurídicas de direito privado, sem fins lucrativos, cujos objetivos sociais tenham pelo menos uma das seguintes finalidades:","I - promoção da assistência social;","II - promoção da cultura, defesa e conservação do patrimônio histórico e artístico;","III - promoção gratuita da educação, observando-se a forma complementar de participação das organizações de que trata esta Lei;","IV - promoção gratuita da saúde, observando-se a forma complementar de participação das organizações de que trata esta Lei;","V - promoção da segurança alimentar e nutricional;","VI - defesa, preservação e conservação do meio ambiente e promoção do desenvolvimento sustentável;","VII - promoção do voluntariado;","VIII - promoção do desenvolvimento econômico e social e combate à pobreza;","IX - experimentação, não lucrativa, de novos modelos sócio-produtivos e de sistemas alternativos de produção, comércio, emprego e crédito;","X - promoção de direitos estabelecidos, construção de novos direitos e assessoria jurídica gratuita de interesse suplementar;","XI - promoção da ética, da paz, da cidadania, dos direitos humanos, da democracia e de outros valores universais;","XII - estudos e pesquisas, desenvolvimento de tecnologias alternativas, produção e divulgação de informações e conhecimentos técnicos e científicos que digam respeito às atividades mencionadas neste artigo.","XIII - estudos e pesquisas para o desenvolvimento, a disponibilização e a implementação de tecnologias voltadas à mobilidade de pessoas, por qualquer meio de transporte. (Inciso acrescido pela Lei nº 13.019, de 31/7/2014, publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação, com a alteração promovida pela Lei nº 13.204, de 14/12/2015)","XIV - disponibilização de produtos ou serviços nas áreas de microcrédito, microcrédito produtivo orientado e microfinanças. (Inciso acrescido pela Lei nº 15.364, de 26/3/2026)","Parágrafo único. Para os fins deste artigo, a dedicação às atividades nele previstas configura-se mediante a execução direta de projetos, programas, planos de ações correlatas, por meio da doação de recursos físicos, humanos e financeiros, ou ainda pela prestação de serviços intermediários de apoio a outras organizações sem fins lucrativos e a órgãos do setor público que atuem em áreas afins."],"url":""},{"key":"l13019:3","law":"l13019","ref":"3","label":"Marco Regulatório das Organizações da Sociedade Civil · Art. 3","paragraphs":["Art. 3º Não se aplicam as exigências desta Lei:","I - às transferências de recursos homologadas pelo Congresso Nacional ou autorizadas pelo Senado Federal naquilo em que as disposições específicas dos tratados, acordos e convenções internacionais conflitarem com esta Lei; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","II - (Revogado pela Lei nº 13.204, de 14/12/2015)","III - aos contratos de gestão celebrados com organizações sociais, desde que cumpridos os requisitos previstos na Lei nº 9.637, de 15 de maio de 1998; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","IV - aos convênios e contratos celebrados com entidades filantrópicas e sem fins lucrativos nos termos do § 1º do art. 199 da Constituição Federal; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","V - aos termos de compromisso cultural referidos no § 1º do art. 9º da Lei nº 13.018, de 22 de julho de 2014; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","VI - aos termos de parceria celebrados com organizações da sociedade civil de interesse público, desde que cumpridos os requisitos previstos na Lei nº 9.790, de 23 de março de 1999; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","VII - às transferências referidas no art. 2º da Lei nº 10.845, de 5 de março de 2004, e nos arts. 5º e 22 da Lei nº 11.947, de 16 de junho de 2009; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","VIII - (VETADO na Lei nº 13.204, de 14/12/2015)","IX - aos pagamentos realizados a título de anuidades, contribuições ou taxas associativas em favor de organismos internacionais ou entidades que sejam obrigatoriamente constituídas por:","a) membros de Poder ou do Ministério Público;","b) dirigentes de órgão ou de entidade da administração pública;","c) pessoas jurídicas de direito público interno;","d) pessoas jurídicas integrantes da administração pública; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","X - às parcerias entre a administração pública e os serviços sociais autônomos. (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)"],"url":""},{"key":"l9790:1","law":"l9790","ref":"1","label":"Lei 9.790/1999 · Art. 1","paragraphs":["Art. 1º Podem qualificar-se como Organizações da Sociedade Civil de Interesse Público as pessoas jurídicas de direito privado sem fins lucrativos que tenham sido constituídas e se encontrem em funcionamento regular há, no mínimo, 3 (três) anos, desde que os respectivos objetivos sociais e normas estatutárias atendam aos requisitos instituídos por esta Lei. (Artigo com redação dada pela Lei nº 13.019, de 31/7/2014, publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação)"],"url":""},{"key":"l9790:5","law":"l9790","ref":"5","label":"Lei 9.790/1999 · Art. 5","paragraphs":["Art. 5º Cumpridos os requisitos dos arts. 3º e 4º desta Lei, a pessoa jurídica de direito privado sem fins lucrativos, interessada em obter a qualificação instituída por esta lei, deverá formular requerimento escrito ao Ministério da Justiça, instruído com cópias autenticadas dos seguintes documentos:","I - estatuto registrado em cartório;","II - ata de eleição de sua atual diretoria;","III - balanço patrimonial e demonstração do resultado do exercício;","IV - declaração de isenção do imposto de renda;","V - inscrição no Cadastro Geral de Contribuintes."],"url":""},{"key":"l9790:6","law":"l9790","ref":"6","label":"Lei 9.790/1999 · Art. 6","paragraphs":["Art. 6º Recebido o requerimento previsto no artigo anterior, o Ministério da Justiça decidirá, no prazo de trinta dias, deferindo ou não o pedido.","§ 1º No caso de deferimento, o Ministério da Justiça emitirá, no prazo de quinze dias da decisão, certificado de qualificação da requerente como Organização da Sociedade Civil de Interesse Público.","§ 2º Indeferido o pedido, o Ministério da Justiça, no prazo do § 1º, dará ciência da decisão, mediante publicação no Diário Oficial.","§ 3º O pedido de qualificação somente será indeferido quando:","I - a requerente enquadrar-se nas hipóteses previstas no art. 2º desta Lei;","II - a requerente não atender aos requisitos descritos nos arts. 3º e 4º desta Lei;","III - a documentação apresentada estiver incompleta."],"url":""},{"key":"l9790:2","law":"l9790","ref":"2","label":"Lei 9.790/1999 · Art. 2","paragraphs":["Art. 2º Não são passíveis de qualificação como Organizações da Sociedade Civil de Interesse Público, ainda que se dediquem de qualquer forma às atividades descritas no art. 3º desta Lei:","I - as sociedades comerciais;","II - os sindicatos, as associações de classe ou de representação de categoria profissional;","III - as instituições religiosas ou voltadas para a disseminação de credos, cultos, práticas e visões devocionais e confessionais;","IV - as organizações partidárias e assemelhadas, inclusive suas fundações;","V - as entidades de benefício mútuo destinadas a proporcionar bens ou serviços a um círculo restrito de associados ou sócios;","VI - as entidades e empresas que comercializam planos de saúde e assemelhados;","VII - as instituições hospitalares privadas não gratuitas e sua mantenedoras;","VIII - as escolas privadas dedicadas ao ensino formal não gratuito e suas mantenedoras;","IX - as organizações sociais;","X - as cooperativas;","XI - as fundações públicas;","XII - as fundações, sociedades civis ou associações de direito privado criadas por órgão público ou por fundações públicas;","XIII - as organizações creditícias que tenham quaisquer tipo de vinculação com o sistema financeiro nacional a que se refere o art. 192 da Constituição Federal.","Parágrafo único. Não constituem impedimento à qualificação como Organização da Sociedade Civil de Interesse Público as operações destinadas a microcrédito, microcrédito produtivo orientado e microfinanças realizadas com instituições financeiras na forma de recebimento de repasses, venda de operações realizadas ou atuação como mandatárias. (Parágrafo único acrescido pela Lei nº 13.999, de 18/5/2020, e com redação dada pela Lei nº 15.364, de 26/3/2026)"],"url":""},{"key":"l9790:4","law":"l9790","ref":"4","label":"Lei 9.790/1999 · Art. 4","paragraphs":["Art. 4º Atendido o disposto no art. 3º, exige-se ainda, para qualificarem-se como Organizações da Sociedade Civil de Interesse Público, que as pessoas jurídicas interessadas sejam regidas por estatutos cujas normas expressamente disponham sobre:","I - a observância dos princípios da legalidade, impessoalidade, moralidade, publicidade, economicidade e da eficiência;","II - a adoção de práticas de gestão administrativa, necessárias e suficientes a coibir a obtenção, de forma individual ou coletiva, de benefícios ou vantagens pessoais, em decorrência da participação no respectivo processo decisório;","III - a constituição de conselho fiscal ou órgão equivalente, dotado de competência para opinar sobre os relatórios de desempenho financeiro e contábil, e sobre as operações patrimoniais realizadas, emitindo pareceres para os organismos superiores da entidade;","IV - a previsão de que, em caso de dissolução da entidade, o respectivo patrimônio líquido será transferido a outra pessoa jurídica qualificada nos termos desta Lei, preferencialmente que tenham o mesmo objeto social da extinta;","V - a previsão de que, na hipótese de a pessoa jurídica perder a qualificação instituída por esta Lei, o respectivo acervo patrimonial disponível, adquirido com recursos públicos durante o período em que perdurou aquela qualificação, será transferido a outra pessoa jurídica qualificada nos termos desta Lei, preferencialmente que tenham o mesmo objeto social;","VI - a possibilidade de se instituir remuneração para os dirigentes da entidade que atuem efetivamente na gestão executiva e para aqueles que a ela prestam serviços específicos, respeitados, em ambos os casos, os valores praticados pelo mercado, na região correspondente a sua área de atuação;","VII - as normas de prestação de contas a serem observadas pela entidade, que determinarão, no mínimo:","a) a observância dos princípios fundamentais de contabilidade e das Normas Brasileiras de Contabilidade;","b) que se dê publicidade por qualquer meio eficaz, no encerramento do exercício fiscal, ao relatório de atividades e das demonstrações financeiras da entidade, incluindo-se as certidões negativas de débitos junto ao INSS e ao FGTS, colocando-os à disposição para exame de qualquer cidadão;","c) a realização de auditoria, inclusive por auditores externos independentes se for o caso, da aplicação dos eventuais recursos objeto do termo de parceria conforme previsto em regulamento;","d) a prestação de contas de todos os recursos e bens de origem pública recebidos pelas Organizações da Sociedade Civil de Interesse Público será feita conforme determina o parágrafo único do art. 70 da Constituição Federal.","Parágrafo único. É permitida a participação de servidores públicos na composição de conselho ou diretoria de Organização da Sociedade Civil de Interesse Público. (Parágrafo único acrescido pela Lei nº 10.539, de 23/9/2002, com redação dada pela Lei nº 13.019, de 31/7/2014, publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação, com a alteração promovida pela Lei nº 13.204, de 14/12/2015)"],"url":""},{"key":"l9790:9","law":"l9790","ref":"9","label":"Lei 9.790/1999 · Art. 9","paragraphs":["Art. 9º Fica instituído o Termo de Parceria, assim considerado o instrumento passível de ser firmado entre o Poder Público e as entidades qualificadas como Organizações da Sociedade Civil de Interesse Público destinado à formação de vínculo de cooperação entre as partes, para o fomento e a execução das atividades de interesse público previstas no art. 3º desta Lei."],"url":""},{"key":"l9790:8","law":"l9790","ref":"8","label":"Lei 9.790/1999 · Art. 8","paragraphs":["Art. 8º Vedado o anonimato, e desde que amparado por fundadas evidências de erro ou fraude, qualquer cidadão, respeitadas as prerrogativas do Ministério Público, é parte legítima para requerer, judicial ou administrativamente, a perda da qualificação instituída por esta Lei."],"url":""},{"key":"l13019:2","law":"l13019","ref":"2","label":"Marco Regulatório das Organizações da Sociedade Civil · Art. 2","paragraphs":["Art. 2º Para os fins desta Lei, considera-se:","I - organização da sociedade civil: (“Caput” do inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","a) entidade privada sem fins lucrativos que não distribua entre os seus sócios ou associados, conselheiros, diretores, empregados, doadores ou terceiros eventuais resultados, sobras, excedentes operacionais, brutos ou líquidos, dividendos, isenções de qualquer natureza, participações ou parcelas do seu patrimônio, auferidos mediante o exercício de suas atividades, e que os aplique integralmente na consecução do respectivo objeto social, de forma imediata ou por meio da constituição de fundo patrimonial ou fundo de reserva; (Alínea acrescida pela Lei nº 13.204, de 14/12/2015)","b) as sociedades cooperativas previstas na Lei nº 9.867, de 10 de novembro de 1999; as integradas por pessoas em situação de risco ou vulnerabilidade pessoal ou social; as alcançadas por programas e ações de combate à pobreza e de geração de trabalho e renda; as voltadas para fomento, educação e capacitação de trabalhadores rurais ou capacitação de agentes de assistência técnica e extensão rural; e as capacitadas para execução de atividades ou de projetos de interesse público e de cunho social. (Alínea acrescida pela Lei nº 13.204, de 14/12/2015)","c) as organizações religiosas que se dediquem a atividades ou a projetos de interesse público e de cunho social distintas das destinadas a fins exclusivamente religiosos; (Alínea acrescida pela Lei nº 13.204, de 14/12/2015)","II - administração pública: União, Estados, Distrito Federal, Municípios e respectivas autarquias, fundações, empresas públicas e sociedades de economia mista prestadoras de serviço público, e suas subsidiárias, alcançadas pelo disposto no § 9º do art. 37 da Constituição Federal; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","III - parceria: conjunto de direitos, responsabilidades e obrigações decorrentes de relação jurídica estabelecida formalmente entre a administração pública e organizações da sociedade civil, em regime de mútua cooperação, para a consecução de finalidades de interesse público e recíproco, mediante a execução de atividade ou de projeto expressos em termos de colaboração, em termos de fomento ou em acordos de cooperação; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","III-A - atividade: conjunto de operações que se realizam de modo contínuo ou permanente, das quais resulta um produto ou serviço necessário à satisfação de interesses compartilhados pela administração pública e pela organização da sociedade civil; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","III-B - projeto: conjunto de operações, limitadas no tempo, das quais resulta um produto destinado à satisfação de interesses compartilhados pela administração pública e pela organização da sociedade civil; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","IV - dirigente: pessoa que detenha poderes de administração, gestão ou controle da organização da sociedade civil, habilitada a assinar termo de colaboração, termo de fomento ou acordo de cooperação com a administração pública para a consecução de finalidades de interesse público e recíproco, ainda que delegue essa competência a terceiros; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","V - administrador público: agente público revestido de competência para assinar termo de colaboração, termo de fomento ou acordo de cooperação com organização da sociedade civil para a consecução de finalidades de interesse público e recíproco, ainda que delegue essa competência a terceiros; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","VI - gestor: agente público responsável pela gestão de parceria celebrada por meio de termo de colaboração ou termo de fomento, designado por ato publicado em meio oficial de comunicação, com poderes de controle e fiscalização; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","VII - termo de colaboração: instrumento por meio do qual são formalizadas as parcerias estabelecidas pela administração pública com organizações da sociedade civil para a consecução de finalidades de interesse público e recíproco propostas pela administração pública que envolvam a transferência de recursos financeiros; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","VIII - termo de fomento: instrumento por meio do qual são formalizadas as parcerias estabelecidas pela administração pública com organizações da sociedade civil para a consecução de finalidades de interesse público e recíproco propostas pelas organizações da sociedade civil, que envolvam a transferência de recursos financeiros; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","VIII-A - acordo de cooperação: instrumento por meio do qual são formalizadas as parcerias estabelecidas pela administração pública com organizações da sociedade civil para a consecução de finalidades de interesse público e recíproco que não envolvam a transferência de recursos financeiros; (Inciso acrescido pela Lei nº 13.204, de 14/12/2015)","IX - conselho de política pública: órgão criado pelo poder público para atuar como instância consultiva, na respectiva área de atuação, na formulação, implementação, acompanhamento, monitoramento e avaliação de políticas públicas;","X - comissão de seleção: órgão colegiado destinado a processar e julgar chamamentos públicos, constituído por ato publicado em meio oficial de comunicação, assegurada a participação de pelo menos um servidor ocupante de cargo efetivo ou emprego permanente do quadro de pessoal da administração pública; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","XI - comissão de monitoramento e avaliação: órgão colegiado destinado a monitorar e avaliar as parcerias celebradas com organizações da sociedade civil mediante termo de colaboração ou termo de fomento, constituído por ato publicado em meio oficial de comunicação, assegurada a participação de pelo menos um servidor ocupante de cargo efetivo ou emprego permanente do quadro de pessoal da administração pública; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","XII - chamamento público: procedimento destinado a selecionar organização da sociedade civil para firmar parceria por meio de termo de colaboração ou de fomento, no qual se garanta a observância dos princípios da isonomia, da legalidade, da impessoalidade, da moralidade, da igualdade, da publicidade, da probidade administrativa, da vinculação ao instrumento convocatório, do julgamento objetivo e dos que lhes são correlatos;","XIII - bens remanescentes: os de natureza permanente adquiridos com recursos financeiros envolvidos na parceria, necessários à consecução do objeto, mas que a ele não se incorporam; (Inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","XIV - prestação de contas: procedimento em que se analisa e se avalia a execução da parceria, pelo qual seja possível verificar o cumprimento do objeto da parceria e o alcance das metas e dos resultados previstos, compreendendo duas fases: (“Caput” do inciso com redação dada pela Lei nº 13.204, de 14/12/2015)","a) apresentação das contas, de responsabilidade da organização da sociedade civil;","b) análise e manifestação conclusiva das contas, de responsabilidade da administração pública, sem prejuízo da atuação dos órgãos de controle;","XV - (Revogado pela Lei nº 13.204, de 14/12/2015)"],"url":""},{"key":"l11107:6","law":"l11107","ref":"6","label":"Lei 11.107/2005 · Art. 6","paragraphs":["Art. 6º O consórcio público adquirirá personalidade jurídica:","I - de direito público, no caso de constituir associação pública, mediante a vigência das leis de ratificação do protocolo de intenções;","II - de direito privado, mediante o atendimento dos requisitos da legislação civil.","§ 1º O consórcio público com personalidade jurídica de direito público integra a administração indireta de todos os entes da Federação consorciados.","§ 2º O consórcio público, com personalidade jurídica de direito público ou privado, observará as normas de direito público no que concerne à realização de licitação, à celebração de contratos, à prestação de contas e à admissão de pessoal, que será regido pela Consolidação das Leis do Trabalho (CLT), aprovada pelo Decreto-Lei nº 5.452, de 1º de maio de 1943. (Parágrafo com redação dada pela Lei nº 13.822, de 3/5/2019)"],"url":""},{"key":"l11107:2","law":"l11107","ref":"2","label":"Lei 11.107/2005 · Art. 2","paragraphs":["Art. 2º Os objetivos dos consórcios públicos serão determinados pelos entes da Federação que se consorciarem, observados os limites constitucionais.","§ 1º Para o cumprimento de seus objetivos, o consórcio público poderá:","I - firmar convênios, contratos, acordos de qualquer natureza, receber auxílios, contribuições e subvenções sociais ou econômicas de outras entidades e órgãos do governo;","II - nos termos do contrato de consórcio de direito público, promover desapropriações e instituir servidões nos termos de declaração de utilidade ou necessidade pública, ou interesse social, realizada pelo Poder Público; e","III - ser contratado pela administração direta ou indireta dos entes da Federação consorciados, dispensada a licitação.","§ 2º Os consórcios públicos poderão emitir documentos de cobrança e exercer atividades de arrecadação de tarifas e outros preços públicos pela prestação de serviços ou pelo uso ou outorga de uso de bens públicos por eles administrados ou, mediante autorização específica, pelo ente da Federação consorciado.","§ 3º Os consórcios públicos poderão outorgar concessão, permissão ou autorização de obras ou serviços públicos mediante autorização prevista no contrato de consórcio público, que deverá indicar de forma específica o objeto da concessão, permissão ou autorização e as condições a que deverá atender, observada a legislação de normas gerais em vigor."],"url":""},{"key":"cf:175","law":"cf","ref":"175","label":"Constituição Federal · CF/88 · Art. 175","paragraphs":["Art. 175. Incumbe ao poder público, na forma da lei, diretamente ou sob regime de concessão ou permissão, sempre através de licitação, a prestação de serviços públicos.","Parágrafo único. A lei disporá sobre:","I - o regime das empresas concessionárias e permissionárias de serviços públicos, o caráter especial de seu contrato e de sua prorrogação, bem como as condições de caducidade, fiscalização e rescisão da concessão ou permissão;","II - os direitos dos usuários;","III - política tarifária;","IV - a obrigação de manter serviço adequado."],"url":""},{"key":"d6017:2","law":"d6017","ref":"2","label":"Decreto 6.017/2007 · Art. 2","paragraphs":["Art. 2º Para os fins deste Decreto, consideram-se:","I - consórcio público: pessoa jurídica formada exclusivamente por entes da Federação, na forma da Lei nº 11.107, de 2005, para estabelecer relações de cooperação federativa, inclusive a realização de objetivos de interesse comum, constituída como associação pública, com personalidade jurídica de direito público e natureza autárquica, ou como pessoa jurídica de direito privado sem fins econômicos;","II - área de atuação do consórcio público: área correspondente à soma dos seguintes territórios, independentemente de figurar a União como consorciada:","a) dos Municípios, quando o consórcio público for constituído somente por Municípios ou por um Estado e Municípios com territórios nele contidos;","b) dos Estados ou dos Estados e do Distrito Federal, quando o consórcio público for, respectivamente, constituído por mais de um Estado ou por um ou mais Estados e o Distrito Federal; e","c) dos Municípios e do Distrito Federal, quando o consórcio for constituído pelo Distrito Federal e Municípios.","III - protocolo de intenções: contrato preliminar que, ratificado pelos entes da Federação interessados, converte-se em contrato de consórcio público;","IV - ratificação: aprovação pelo ente da Federação, mediante lei, do protocolo de intenções ou do ato de retirada do consórcio público;","V - reserva: ato pelo qual ente da Federação não ratifica, ou condiciona a ratificação, de determinado dispositivo de protocolo de intenções;","VI - retirada: saída de ente da Federação de consórcio público, por ato formal de sua vontade;","VII - contrato de rateio: contrato por meio do qual os entes consorciados comprometem-se a fornecer recursos financeiros para a realização das despesas do consórcio público;","VIII - convênio de cooperação entre entes federados: pacto firmado exclusivamente por entes da Federação, com o objetivo de autorizar a gestão associada de serviços públicos, desde que ratificado ou previamente disciplinado por lei editada por cada um deles;","IX - gestão associada de serviços públicos: exercício das atividades de planejamento, regulação ou fiscalização de serviços públicos por meio de consórcio público ou de convênio de cooperação entre entes federados, acompanhadas ou não da prestação de serviços públicos ou da transferência total ou parcial de encargos, serviços, pessoal e bens essenciais à continuidade dos serviços transferidos;","X - planejamento: as atividades atinentes à identificação, qualificação, quantificação, organização e orientação de todas as ações, públicas e privadas, por meio das quais um serviço público deve ser prestado ou colocado à disposição de forma adequada;","XI - regulação: todo e qualquer ato, normativo ou não, que discipline ou organize um determinado serviço público, incluindo suas características, padrões de qualidade, impacto sócio-ambiental, direitos e obrigações dos usuários e dos responsáveis por sua oferta ou prestação e fixação e revisão do valor de tarifas e outros preços públicos;","XII - fiscalização: atividades de acompanhamento, monitoramento, controle ou avaliação, no sentido de garantir a utilização, efetiva ou potencial, do serviço público;","XIII - prestação de serviço público em regime de gestão associada: execução, por meio de cooperação federativa, de toda e qualquer atividade ou obra com o objetivo de permitir aos usuários o acesso a um serviço público com características e padrões de qualidade determinados pela regulação ou pelo contrato de programa, inclusive quando operada por transferência total ou parcial de encargos, serviços, pessoal e bens essenciais à continuidade dos serviços transferidos;","XIV - serviço público: atividade ou comodidade material fruível diretamente pelo usuário, que possa ser remunerado por meio de taxa ou preço público, inclusive tarifa;","XV - titular de serviço público: ente da Federação a quem compete prover o serviço público, especialmente por meio de planejamento, regulação, fiscalização e prestação direta ou indireta;","XVI - contrato de programa: instrumento pelo qual devem ser constituídas e reguladas as obrigações que um ente da Federação, inclusive sua administração indireta, tenha para com outro ente da Federação, ou para com consórcio público, no âmbito da prestação de serviços públicos por meio de cooperação federativa;","XVII - termo de parceria: instrumento passível de ser firmado entre consórcio público e entidades qualificadas como Organizações da Sociedade Civil de Interesse Público, destinado à formação de vínculo de cooperação entre as partes para o fomento e a execução de atividades de interesse público previstas no art. 3º da Lei nº 9.790, de 23 de março de 1999; e","XVIII - contrato de gestão: instrumento firmado entre a administração pública e autarquia ou fundação qualificada como Agência Executiva, na forma do art. 51 da Lei nº 9.649, de 27 de maio de 1998, por meio do qual se estabelecem objetivos, metas e respectivos indicadores de desempenho da entidade, bem como os recursos necessários e os critérios e instrumentos para a avaliação do seu cumprimento.","Parágrafo único. A área de atuação do consórcio público mencionada no inciso II do caput deste artigo refere-se exclusivamente aos territórios dos entes da Federação que tenham ratificado por lei o protocolo de intenções."],"url":""},{"key":"l11107:12","law":"l11107","ref":"12","label":"Lei 11.107/2005 · Art. 12","paragraphs":["Art. 12. A extinção de contrato de consórcio público dependerá de instrumento aprovado pela assembleia geral, ratificado mediante lei por todos os entes consorciados. (“Caput” do artigo com redação dada pela Lei nº 14.662, de 24/8/2023)","§ 1º (Revogado pela Lei nº 14.026, de 15/7/2020)","§ 2º Até que haja decisão que indique os responsáveis por cada obrigação, os entes consorciados responderão solidariamente pelas obrigações remanescentes, garantindo o direito de regresso em face dos entes beneficiados ou dos que deram causa à obrigação."],"url":""},{"key":"l11107:12-A","law":"l11107","ref":"12-A","label":"Lei 11.107/2005 · Art. 12-A","paragraphs":["Art. 12-A. A alteração de contrato de consórcio público dependerá de instrumento aprovado pela assembleia geral, ratificado mediante lei pela maioria dos entes consorciados. (Artigo acrescido pela Lei nº 14.662, de 24/8/2023)"],"url":""},{"key":"d6017:29","law":"d6017","ref":"29","label":"Decreto 6.017/2007 · Art. 29","paragraphs":["Art. 29. A alteração ou a extinção do contrato de consórcio público dependerá de instrumento aprovado pela assembléia geral, ratificado mediante lei por todos os entes consorciados.","§ 1º Em caso de extinção:","I - os bens, direitos, encargos e obrigações decorrentes da gestão associada de serviços públicos custeados por tarifas ou outra espécie de preço público serão atribuídos aos titulares dos respectivos serviços;","II - até que haja decisão que indique os responsáveis por cada obrigação, os entes consorciados responderão solidariamente pelas obrigações remanescentes, garantido o direito de regresso em face dos entes beneficiados ou dos que deram causa à obrigação.","§ 2º Com a extinção, o pessoal cedido ao consórcio público retornará aos seus órgãos de origem, e os empregados públicos terão automaticamente rescindidos os seus contratos de trabalho com o consórcio."],"url":""},{"key":"l11107:1","law":"l11107","ref":"1","label":"Lei 11.107/2005 · Art. 1","paragraphs":["Art. 1º Esta Lei dispõe sobre normas gerais para a União, os Estados, o Distrito Federal e os Municípios contratarem consórcios públicos para a realização de objetivos de interesse comum e dá outras providências.","§ 1º O consórcio público constituirá associação pública ou pessoa jurídica de direito privado.","§ 2º A União somente participará de consórcios públicos em que também façam parte todos os Estados em cujos territórios estejam situados os Municípios consorciados.","§ 3º Os consórcios públicos, na área de saúde, deverão obedecer aos princípios, diretrizes e normas que regulam o Sistema Único de Saúde - SUS.","§ 4º Aplicam-se aos convênios de cooperação, no que couber, as disposições desta Lei relativas aos consórcios públicos. (Parágrafo acrescido pela Lei nº 14.026, de 15/7/2020)"],"url":""},{"key":"l9637:3","law":"l9637","ref":"3","label":"Lei 9.637/1998 · Art. 3","paragraphs":["Art. 3º O conselho de administração deve estar estruturado nos termos que dispuser o respectivo estatuto, observados, para os fins de atendimento dos requisitos de qualificação, os seguintes critérios básicos:","I - ser composto por:","a) 20 a 40% (vinte a quarenta por cento) de membros natos representantes do Poder Público, definidos pelo estatuto da entidade;","b) 20 a 30% (vinte a trinta por cento) de membros natos representantes de entidades da sociedade civil, definidos pelo estatuto;","c) até 10% (dez por cento), no caso de associação civil, de membros eleitos dentre os membros ou os associados;","d) 10 a 30% (dez a trinta por cento) de membros eleitos pelos demais integrantes do conselho, dentre pessoas de notória capacidade profissional e reconhecida idoneidade moral;","e) até 10% (dez por cento) de membros indicados ou eleitos na forma estabelecida pelo estatuto;","II - os membros eleitos ou indicados para compor o Conselho devem ter mandato de quatro anos, admitida uma recondução;","III - os representantes de entidades previstos nas alíneas \"a\" e \"b\" do inciso I devem corresponder a mais de 50% (cinquenta por cento) do Conselho;","IV - o primeiro mandato de metade dos membros eleitos ou indicados deve ser de dois anos, segundo critérios estabelecidos no estatuto;","V - o dirigente máximo da entidade deve participar das reuniões do conselho, sem direito a voto;","VI - o Conselho deve reunir-se ordinariamente, no mínimo, três vezes a cada ano e, extraordinariamente, a qualquer tempo;","VII - os conselheiros não devem receber remuneração pelos serviços que, nesta condição, prestarem à organização social, ressalvada a ajuda de custo por reunião da qual participem;","VIII - os conselheiros eleitos ou indicados para integrar a diretoria da entidade devem renunciar ao assumirem funções executivas."],"url":""},{"key":"l9637:4","law":"l9637","ref":"4","label":"Lei 9.637/1998 · Art. 4","paragraphs":["Art. 4º Para os fins de atendimento dos requisitos de qualificação, devem ser atribuições privativas do Conselho de Administração, dentre outras:","I - fixar o âmbito de atuação da entidade, para consecução do seu objeto;","II - aprovar a proposta de contrato de gestão da entidade;","III - aprovar a proposta de orçamento da entidade e o programa de investimentos;","IV - designar e dispensar os membros da diretoria;","V - fixar a remuneração dos membros da diretoria;","VI - aprovar e dispor sobre a alteração dos estatutos e a extinção da entidade por maioria, no mínimo, de dois terços de seus membros;","VII - aprovar o regimento interno da entidade, que deve dispor, no mínimo, sobre a estrutura, forma de gerenciamento, os cargos e respectivas competências;","VIII - aprovar por maioria, no mínimo, de dois terços de seus membros, o regulamento próprio contendo os procedimentos que deve adotar para a contratação de obras, serviços, compras e alienações e o plano de cargos, salários e benefícios dos empregados da entidade;","IX - aprovar e encaminhar, ao órgão supervisor da execução do contrato de gestão, os relatórios gerenciais e de atividades da entidade, elaborados pela diretoria;","X - fiscalizar o cumprimento das diretrizes e metas definidas e aprovar os demonstrativos financeiros e contábeis e as contas anuais da entidade, com o auxílio de auditoria externa."],"url":""},{"key":"l9637:10","law":"l9637","ref":"10","label":"Lei 9.637/1998 · Art. 10","paragraphs":["Art. 10. Sem prejuízo da medida a que se refere o artigo anterior, quando assim exigir a gravidade dos fatos ou o interesse público, havendo indícios fundados de malversação de bens ou recursos de origem pública, os responsáveis pela fiscalização representarão ao Ministério Público, à Advocacia-Geral da União ou à Procuradoria da entidade para que requeira ao juízo competente a decretação da indisponibilidade dos bens da entidade e o seqüestro dos bens dos seus dirigentes, bem como de agente público ou terceiro, que possam ter enriquecido ilicitamente ou causado dano ao patrimônio público.","§ 1º O pedido de seqüestro será processado de acordo com o disposto nos arts. 822 e 825 do Código de Processo Civil.","§ 2º Quando for o caso, o pedido incluirá a investigação, o exame e o bloqueio de bens, contas bancárias e aplicações mantidas pelo demandado no País e no exterior, nos termos da lei e dos tratados internacionais.","§ 3º Até o término da ação, o Poder Público permanecerá como depositário e gestor dos bens e valores seqüestrados ou indisponíveis e velará pela continuidade das atividades sociais da entidade."],"url":""},{"key":"l9637:8","law":"l9637","ref":"8","label":"Lei 9.637/1998 · Art. 8","paragraphs":["Art. 8º A execução do contrato de gestão celebrado por organização social será fiscalizada pelo órgão ou entidade supervisora da área de atuação correspondente à atividade fomentada.","§ 1º A entidade qualificada apresentará ao órgão ou entidade do Poder Público supervisora signatária do contrato, ao término de cada exercício ou a qualquer momento, conforme recomende o interesse público, relatório pertinente à execução do contrato de gestão, contendo comparativo específico das metas propostas com os resultados alcançados, acompanhado da prestação de contas correspondente ao exercício financeiro.","§ 2º Os resultados atingidos com a execução do contrato de gestão devem ser analisados, periodicamente, por comissão de avaliação, indicada pela autoridade supervisora da área correspondente, composta por especialistas de notória capacidade e adequada qualificação.","§ 3º A comissão deve encaminhar à autoridade supervisora relatório conclusivo sobre a avaliação procedida."],"url":""},{"key":"l9637:9","law":"l9637","ref":"9","label":"Lei 9.637/1998 · Art. 9","paragraphs":["Art. 9º Os responsáveis pela fiscalização da execução do contrato de gestão, ao tomarem conhecimento de qualquer irregularidade ou ilegalidade na utilização de recursos ou bens de origem pública por organização social, dela darão ciência ao Tribunal de Contas da União, sob pena de responsabilidade solidária."],"url":""},{"key":"l9637:11","law":"l9637","ref":"11","label":"Lei 9.637/1998 · Art. 11","paragraphs":["Art. 11. As entidades qualificadas como organizações sociais são declaradas como entidades de interesse social e utilidade pública, para todos os efeitos legais."],"url":""},{"key":"l9637:12","law":"l9637","ref":"12","label":"Lei 9.637/1998 · Art. 12","paragraphs":["Art. 12. Às organizações sociais poderão ser destinados recursos orçamentários e bens públicos necessários ao cumprimento do contrato de gestão.","§ 1° São assegurados às organizações sociais os créditos previstos no orçamento e as respectivas liberações financeiras, de acordo com o cronograma de desembolso previsto no contrato de gestão.","§ 2º Poderá ser adicionada aos créditos orçamentários destinados ao custeio do contrato de gestão parcela de recursos para compensar desligamento de servidor cedido, desde que haja justificativa expressa da necessidade pela organização social.","§ 3º Os bens de que trata este artigo serão destinados às organizações sociais, dispensada licitação, mediante permissão de uso, consoante cláusula expressa do contrato de gestão. (Vide ADIN nº 1.923/1998)"],"url":""},{"key":"l9637:13","law":"l9637","ref":"13","label":"Lei 9.637/1998 · Art. 13","paragraphs":["Art. 13. Os bens móveis públicos permitidos para uso poderão ser permutados por outros de igual ou maior valor, condicionado a que os novos bens integrem o patrimônio da União.","Parágrafo único. A permuta de que trata este artigo dependerá de prévia avaliação do bem e expressa autorização do Poder Público."],"url":""},{"key":"l9637:15","law":"l9637","ref":"15","label":"Lei 9.637/1998 · Art. 15","paragraphs":["Art. 15. São extensíveis, no âmbito da União, os efeitos dos arts. 11 e 12, § 3º, para as entidades qualificadas como organizações sociais pelos Estados, pelo Distrito Federal e pelos Municípios, quando houver reciprocidade e desde que a legislação local não contrarie os preceitos desta Lei e a legislação específica de âmbito federal."],"url":""},{"key":"l9637:16","law":"l9637","ref":"16","label":"Lei 9.637/1998 · Art. 16","paragraphs":["Art. 16. O Poder Executivo poderá proceder à desqualificação da entidade como organização social, quando constatado o descumprimento das disposições contidas no contrato de gestão.","§ 1º A desqualificação será precedida de processo administrativo, assegurado o direito de ampla defesa, respondendo os dirigentes da organização social, individual e solidariamente, pelos danos ou prejuízos decorrentes de sua ação ou omissão.","§ 2º A desqualificação importará reversão dos bens permitidos e dos valores entregues à utilização da organização social, sem prejuízo de outras sanções cabíveis."],"url":""},{"key":"l9790:7","law":"l9790","ref":"7","label":"Lei 9.790/1999 · Art. 7","paragraphs":["Art. 7º Perde-se a qualificação de Organização da Sociedade Civil de Interesse Público, a pedido ou mediante decisão proferida em processo administrativo ou judicial, de iniciativa popular ou do Ministério Público, no qual serão assegurados, ampla defesa e o devido contraditório."],"url":""},{"key":"l9790:15-B","law":"l9790","ref":"15-B","label":"Lei 9.790/1999 · Art. 15-B","paragraphs":["Art. 15-B. A prestação de contas relativa à execução do Termo de Parceria perante o órgão da entidade estatal parceira refere-se à correta aplicação dos recursos públicos recebidos e ao adimplemento do objeto do Termo de Parceria, mediante a apresentação dos seguintes documentos:","I - relatório anual de execução de atividades, contendo especificamente relatório sobre a execução do objeto do Termo de Parceria, bem como comparativo entre as metas propostas e os resultados alcançados;","II - demonstrativo integral da receita e despesa realizadas na execução;","III - extrato da execução física e financeira;","IV - demonstração de resultados do exercício;","V - balanço patrimonial;","VI - demonstração das origens e das aplicações de recursos;","VII - demonstração das mutações do patrimônio social;","VIII - notas explicativas das demonstrações contábeis, caso necessário;","IX - parecer e relatório de auditoria, se for o caso. (Artigo acrescido pela Lei nº 13.019, de 31/7/2014, publicada no DOU de 1/8/2014, em vigor 540 dias após a publicação)"],"url":""},{"key":"l9790:10","law":"l9790","ref":"10","label":"Lei 9.790/1999 · Art. 10","paragraphs":["Art. 10. O Termo de Parceria firmado de comum acordo entre o Poder Público e as Organizações da Sociedade Civil de Interesse Público discriminará direitos, responsabilidades e obrigações das partes signatárias.","§ 1º A celebração do Termo de Parceria será precedida de consulta aos Conselhos de Políticas Públicas das áreas correspondentes de atuação existentes, nos respectivos níveis de governo.","§ 2º São cláusulas essenciais do Termo de Parceria:","I - a do objeto, que conterá a especificação do programa de trabalho proposto pela Organização da Sociedade Civil de Interesse Público;","II - a de estipulação das metas e dos resultados a serem atingidos e os respectivos prazos de execução ou cronograma;","III - a de previsão expressa dos critérios objetivos de avaliação de desempenho a serem utilizados, mediante indicadores de resultado;","IV - a de previsão de receitas e despesas a serem realizadas em seu cumprimento, estipulando item por item as categorias contábeis usadas pela organização e o detalhamento das remunerações e benefícios de pessoal a serem pagos, com recursos oriundos ou vinculados ao Termo de Parceria, a seus diretores, empregados e consultores;","V - a que estabelece as obrigações da Sociedade Civil de Interesse Público, entre as quais a de apresentar ao Poder Público, ao término de cada exercício, relatório sobre a execução do objeto do Termo de Parceria, contendo comparativo específico das metas propostas com os resultados alcançados, acompanhado de prestação de contas dos gastos e receitas efetivamente realizados, independente das previsões mencionadas no inciso IV;","VI - a de publicação, na imprensa oficial do Município, do Estado ou da União, conforme o alcance das atividades celebradas entre o órgão parceiro e a Organização da Sociedade Civil de Interesse Público, de estrato do Termo de Parceria e de demonstrativo da sua execução física e financeira, conforme modelo simplificado estabelecido no regulamento desta Lei, contendo os dados principais da documentação obrigatória do inciso V, sob pena de não liberação dos recursos previstos no Termo de Parceria."],"url":""},{"key":"l9790:11","law":"l9790","ref":"11","label":"Lei 9.790/1999 · Art. 11","paragraphs":["Art. 11. A execução do objeto do Termo de Parceria será acompanhada e fiscalizada por órgão do Poder Público da área de atuação correspondente à atividade fomentada, e pelos Conselhos de Políticas Públicas das áreas correspondentes de atuação existentes, em cada nível de governo.","§ 1º Os resultados atingidos com a execução do Termo de Parceria devem ser analisados por comissão de avaliação, composta de comum acordo entre o órgão parceiro e a Organização da Sociedade Civil de Interesse Público.","§ 2º A comissão encaminhará à autoridade competente relatório conclusivo sobre a avaliação procedida.","§ 3º Os Termos de Parceria destinados ao fomento de atividades nas áreas de que trata esta Lei estarão sujeitos aos mecanismos de controle social previstos na legislação."],"url":""},{"key":"l9790:12","law":"l9790","ref":"12","label":"Lei 9.790/1999 · Art. 12","paragraphs":["Art. 12. Os responsáveis pela fiscalização do Termo de Parceria, ao tomarem conhecimento de qualquer irregularidade ou ilegalidade na utilização de recursos ou bens de origem pública pela organização parceira, darão imediata ciência ao Tribunal de Contas respectivo e ao Ministério Público, sob pena de responsabilidade solidária."],"url":""},{"key":"l9790:13","law":"l9790","ref":"13","label":"Lei 9.790/1999 · Art. 13","paragraphs":["Art. 13. Sem prejuízo da medida a que se refere o art. 12 desta Lei, havendo indícios fundados de malversação de bens ou recursos de origem pública, os responsáveis pela fiscalização representarão ao Ministério Público, à Advocacia-Geral da União, para que requeiram ao juízo competente a decretação da indisponibilidade dos bens da entidade e o seqüestro dos bens dos seus dirigentes, bem como de agente público ou terceiro, que possam ter enriquecido ilicitamente ou causado dano ao patrimônio público, além de outras medidas consubstanciadas na Lei nº 8.429, de 2 de junho de 1992, e na Lei Complementar nº 64, de 18 de maio de 1990.","§ 1º O pedido de seqüestro será processado de acordo com o disposto nos arts. 822 e 825 do Código de Processo Civil.","§ 2º Quando for o caso, o pedido incluirá a investigação, o exame e o bloqueio de bens, contas bancárias e aplicações mantidas pelo demandado no País e no exterior, nos termos da lei dos tratados internacionais.","§ 3º Até o término da ação, o Poder Público permanecerá como depositário e gestor dos bens e valores seqüestrados ou indisponíveis e velará pela continuidade das atividades sociais da organização parceira."],"url":""},{"key":"l9790:14","law":"l9790","ref":"14","label":"Lei 9.790/1999 · Art. 14","paragraphs":["Art. 14. A organização parceira fará publicar, no prazo máximo de trinta dias, contado da assinatura do Termo de Parceira, regulamento próprio contendo os procedimentos que adotará para a contratação de obras e serviços, bem como para compras com emprego de recursos provenientes do Poder Público, observado os princípios estabelecidos no inciso I do art. 4º desta Lei."],"url":""},{"key":"l9790:15","law":"l9790","ref":"15","label":"Lei 9.790/1999 · Art. 15","paragraphs":["Art. 15. Caso a organização adquira bem imóvel com recursos provenientes da celebração do Termo de Parceria, este será gravado com cláusula de inalienabilidade."],"url":""},{"key":"l9790:15-A","law":"l9790","ref":"15-A","label":"Lei 9.790/1999 · Art. 15-A","paragraphs":["Art. 15-A. (VETADO na Lei nº 13.019, de 31/7/2014)"],"url":""},{"key":"l13019:16","law":"l13019","ref":"16","label":"Marco Regulatório das Organizações da Sociedade Civil · Art. 16","paragraphs":["Art. 16. O termo de colaboração deve ser adotado pela administração pública para consecução de planos de trabalho de sua iniciativa, para celebração de parcerias com organizações da sociedade civil que envolvam a transferência de recursos financeiros. (“Caput” do artigo com redação dada pela Lei nº 13.204, de 14/12/2015)","Parágrafo único. Os conselhos de políticas públicas poderão apresentar propostas à administração pública para celebração de termo de colaboração com organizações da sociedade civil."],"url":""},{"key":"l13019:17","law":"l13019","ref":"17","label":"Marco Regulatório das Organizações da Sociedade Civil · Art. 17","paragraphs":["Art. 17. O termo de fomento deve ser adotado pela administração pública para consecução de planos de trabalho propostos por organizações da sociedade civil que envolvam a transferência de recursos financeiros. (Artigo com redação dada pela Lei nº 13.204, de 14/12/2015)"],"url":""},{"key":"l8958:1","law":"l8958","ref":"1","label":"Lei 8.958/1994 · Art. 1","paragraphs":["Art. 1º As Instituições Federais de Ensino Superior – IFES e as demais Instituições Científicas e Tecnológicas - ICTs, de que trata a Lei nº 10.973, de 2 de dezembro de 2004, poderão celebrar convênios e contratos, nos termos do inciso XIII do caput do art. 24 da Lei nº 8.666, de 21 de junho de 1993, por prazo determinado, com fundações instituídas com a finalidade de apoiar projetos de ensino, pesquisa, extensão, desenvolvimento institucional, científico e tecnológico e estímulo à inovação, inclusive na gestão administrativa e financeira necessária à execução desses projetos. (“Caput” do artigo com redação dada pela Lei nº 12.863, de 24/9/2013)","§ 1º Para os fins do que dispõe esta Lei, entendem-se por desenvolvimento institucional os programas, projetos, atividades e operações especiais, inclusive de natureza infraestrutural, material e laboratorial, que levem à melhoria mensurável das condições das IFES e demais ICTs, para cumprimento eficiente e eficaz de sua missão, conforme descrita no plano de desenvolvimento institucional, vedada, em qualquer caso, a contratação de objetos genéricos, desvinculados de projetos específicos. (Parágrafo acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 2º A atuação da fundação de apoio em projetos de desenvolvimento institucional para melhoria de infraestrutura limitar- se-á às obras laboratoriais e à aquisição de materiais, equipamentos e outros insumos diretamente relacionados às atividades de inovação e pesquisa científica e tecnológica. (Parágrafo acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 3º É vedado o enquadramento no conceito de desenvolvimento institucional, quando financiadas com recursos repassados pelas IFES e demais ICTs às fundações de apoio, de: (Parágrafo acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","I - atividades como manutenção predial ou infraestrutural, conservação, limpeza, vigilância, reparos, copeiragem, recepção, secretariado, serviços administrativos na área de informática, gráficos, reprográficos e de telefonia e demais atividades administrativas de rotina, bem como as respectivas expansões vegetativas, inclusive por meio do aumento no número total de pessoal; e (Inciso acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","II - outras tarefas que não estejam objetivamente definidas no Plano de Desenvolvimento Institucional da instituição apoiada. (Inciso acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 3º-A. No caso da Fundação Oswaldo Cruz (Fiocruz), na condição de ICT, o convênio ou contrato com a fundação de apoio, de que trata o caput deste artigo, poderá abranger o apoio a projetos de produção e fornecimento de vacinas, medicamentos e outros insumos e serviços para a saúde, nos termos das competências da Fiocruz, aplicando-se a esses projetos o disposto no § 1º do art. 3º desta Lei. (Parágrafo acrescido pela Lei nº 13.801, de 9/1/2019)","§ 3º-B. No caso da Fiocruz, na condição de ICT, o convênio ou o contrato com a fundação de apoio de que trata o caput deste artigo, nas situações de urgência em saúde pública de que trata o § 4º do art. 16 da Lei nº 8.080, de 19 de setembro de 1990 (Lei Orgânica da Saúde), poderá abranger o apoio a políticas e a projetos nacionais de estruturação da atenção especializada, com a possibilidade de contratação de pessoas e de serviços, observadas as competências da Fiocruz, aplicando-se a esses projetos o disposto no art. 3º desta Lei. (Parágrafo acrescido pela Medida Provisória nº 1.301, de 30/5/2025, convertida na Lei nº 15.233, de 7/10/2025)","§ 4º É vedada a subcontratação total do objeto dos ajustes realizados pelas IFES e demais ICTs com as fundações de apoio, com base no disposto nesta Lei, bem como a subcontratação parcial que delegue a terceiros a execução do núcleo do objeto contratado. (Parágrafo acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 5º Os materiais e equipamentos adquiridos com recursos transferidos com fundamento no § 2º integrarão o patrimônio da contratante. (Parágrafo acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 6º Os parques e polos tecnológicos, as incubadoras de empresas, as associações e as empresas criados com a participação de ICT pública poderão utilizar fundação de apoio a ela vinculada ou com a qual tenham acordo. (Parágrafo acrescido pela Lei nº 13.243, de 11/1/2016)","§ 7º Os recursos e direitos provenientes dos projetos de que trata o caput e das atividades e dos projetos de que tratam os arts. 3º a 9º, 11 e 13 da Lei no 10.973, de 2 de dezembro de 2004, poderão ser repassados pelos contratantes diretamente para as fundações de apoio. (Parágrafo acrescido pela Lei nº 13.243, de 11/1/2016)","§ 8º O Núcleo de Inovação Tecnológica constituído no âmbito de ICT poderá assumir a forma de fundação de apoio de que trata esta Lei. (Parágrafo acrescido pela Lei nº 13.243, de 11/1/2016)"],"url":""},{"key":"l8958:4-D","law":"l8958","ref":"4-D","label":"Lei 8.958/1994 · Art. 4-D","paragraphs":["Art. 4º - D. A movimentação dos recursos dos projetos gerenciados pelas fundações de apoio deverá ser realizada exclusivamente por meio eletrônico, mediante crédito em conta corrente de titularidade dos fornecedores e prestadores de serviços devidamente identificados.","§ 1º Poderão ser realizados, mediante justificativa circunstanciada e em caráter excepcional, saques para pagamento em dinheiro a pessoas físicas que não possuam conta bancária ou saques para atender a despesas de pequeno vulto, definidas em regulamento específico previsto no art. 3º desta Lei, adotando-se, em ambas as hipóteses, mecanismos que permitam a identificação do beneficiário final, devendo as informações sobre tais pagamentos constar em item específico da prestação de contas.","§ 2º Os recursos provenientes de convênios, contratos, acordos e demais ajustes que envolvam recursos públicos gerenciados pelas fundações de apoio deverão ser mantidos em contas específicas abertas para cada projeto.","§ 3º As fundações de apoio deverão garantir o controle contábil específico dos recursos aportados e utilizados em cada projeto, de forma a garantir o ressarcimento às IFES, previsto no art. 6º desta Lei. (Artigo acrescido pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l8958:1-A","law":"l8958","ref":"1-A","label":"Lei 8.958/1994 · Art. 1-A","paragraphs":["Art. 1º - A. A Financiadora de Estudos e Projetos - FINEP, como secretaria executiva do Fundo Nacional de Desenvolvimento Científico e Tecnológico - FNDCT, o Conselho Nacional de Desenvolvimento Científico e Tecnológico - CNPq, as agências financeiras oficiais de fomento e empresas públicas ou sociedades de economia mista, suas subsidiárias ou controladas, poderão celebrar convênios e contratos, nos termos do inciso XIII do caput do art. 24 da Lei nº 8.666, de 21 de junho de 1993, por prazo determinado, com as fundações de apoio, com finalidade de dar apoio às IFES e às demais ICTs, inclusive na gestão administrativa e financeira dos projetos mencionados no caput do art. 1º, com a anuência expressa das instituições apoiadas. (Artigo acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l8958:1-B","law":"l8958","ref":"1-B","label":"Lei 8.958/1994 · Art. 1-B","paragraphs":["Art. 1º - B. As organizações sociais e entidades privadas poderão realizar convênios e contratos, por prazo determinado, com as fundações de apoio, com a finalidade de dar apoio às IFES e às demais ICTs, inclusive na gestão administrativa e financeira dos projetos mencionados no caput do art. 1º , com a anuência expressa das instituições apoiadas.","Parágrafo único. A celebração de convênios entre a IFES ou demais ICTs apoiadas, fundação de apoio, entidades privadas, empresas públicas ou sociedades de economia mista, suas subsidiárias ou controladas, e organizações sociais, para finalidades de pesquisa, desenvolvimento, estímulo e fomento à inovação, será realizada mediante critérios de habilitação das empresas, regulamentados em ato do Poder Executivo federal, não se aplicando nesses casos a legislação federal que institui normas para licitações e contratos da administração pública para a identificação e escolha das empresas convenentes. (Artigo acrescido pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l8958:1-C","law":"l8958","ref":"1-C","label":"Lei 8.958/1994 · Art. 1-C","paragraphs":["Art. 1º - C. Os convênios de que trata esta Lei serão regulamentados por ato do Poder Executivo federal. (Artigo acrescido pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l8958:2","law":"l8958","ref":"2","label":"Lei 8.958/1994 · Art. 2","paragraphs":["Art. 2º. As fundações a que se refere o art. 1º deverão estar constituídas na forma de fundações de direito privado, sem fins lucrativos, regidas pela Lei nº 10.406, de 10 de janeiro de 2002 - Código Civil, e por estatutos cujas normas expressamente disponham sobre a observância dos princípios da legalidade, impessoalidade, moralidade, publicidade, economicidade e eficiência, e sujeitas, em especial: (“Caput” do artigo com redação dada pela Lei nº 12.349, de 15/12/2010)","I - a fiscalização pelo Ministério Público, nos termos do Código Civil e do Código de Processo Civil;","II - à legislação trabalhista; (Inciso com redação dada pela Medida Provisória nº 785, de 6/7/2017, convertida na Lei nº 13.530, de 7/12/2017)","III - ao prévio credenciamento no Ministério da Educação e no Ministério da Ciência, Tecnologia, Inovações e Comunicações, renovável a cada 5 (cinco) anos. (Inciso com redação dada pela Medida Provisória nº 785, de 6/7/2017, convertida na Lei nº 13.530, de 7/12/2017)","Parágrafo único. Em caso de renovação do credenciamento, prevista no inciso III do caput, o Conselho Superior ou o órgão competente da instituição federal a ser apoiada deverá se manifestar quanto ao cumprimento pela fundação de apoio das disposições contidas no art. 4º -A. (Parágrafo único acrescido pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l8958:3","law":"l8958","ref":"3","label":"Lei 8.958/1994 · Art. 3","paragraphs":["Art. 3º Na execução de convênios, contratos, acordos e demais ajustes abrangidos por esta Lei que envolvam recursos provenientes do poder público, as fundações de apoio adotarão regulamento específico de aquisições e contratações de obras e serviços, a ser editado por meio de ato do Poder Executivo de cada nível de governo. (“Caput” do artigo com redação dada pela Lei nº 13.243, de 11/1/2016)","I – (Revogado pela Lei nº 12.863, de 24/9/2013)","II - (Revogado pela Lei nº 12.863, de 24/9/2013)","III - (Revogado pela Lei nº 12.863, de 24/9/2013)","IV - (Revogado pela Lei nº 12.863, de 24/9/2013))","§ 1º As fundações de apoio, com a anuência expressa das instituições apoiadas, poderão captar e receber diretamente os recursos financeiros necessários à formação e à execução dos projetos de pesquisa, desenvolvimento e inovação, sem ingresso na Conta Única do Tesouro Nacional. (Parágrafo acrescido pela Lei nº 12.863, de 24/9/2013)","§ 2º As fundações de apoio não poderão:","I - contratar cônjuge, companheiro ou parente, em linha reta ou colateral, por consanguinidade ou afinidade, até o terceiro grau, de:","a) servidor das IFES e demais ICTs que atue na direção das respectivas fundações; e","b) ocupantes de cargos de direção superior das IFES e demais ICTs por elas apoiadas;","II - contratar, sem licitação, pessoa jurídica que tenha como proprietário, sócio ou cotista:","a) seu dirigente;","b) servidor das IFES e demais ICTs; e","c) cônjuge, companheiro ou parente em linha reta ou colateral, por consanguinidade ou afinidade, até o terceiro grau de seu dirigente ou de servidor das IFES e demais ICTs por elas apoiadas; e","III - utilizar recursos em finalidade diversa da prevista nos projetos de ensino, pesquisa e extensão e de desenvolvimento institucional, científico e tecnológico e de estímulo à inovação. (Parágrafo acrescido pela Lei nº 12.863, de 24/9/2013)","§ 3º Aplicam-se às contratações que não envolvam a aplicação de recursos públicos as regras instituídas pela instância superior da fundação de apoio, disponíveis em seu sítio eletrônico, respeitados os princípios mencionados no art. 2º desta Lei. (Parágrafo acrescido pela Lei nº 13.243, de 11/1/2016)"],"url":""},{"key":"l8958:3-A","law":"l8958","ref":"3-A","label":"Lei 8.958/1994 · Art. 3-A","paragraphs":["Art. 3º - A. Na execução de convênios, contratos, acordos e demais ajustes na forma desta Lei, as fundações de apoio deverão:","I - prestar contas dos recursos aplicados aos entes financiadores;","II - submeter-se ao controle de gestão pelo órgão máximo da","Instituição Federal de Ensino ou similar da entidade contratante; e","III - submeter-se ao controle finalístico pelo órgão de controle governamental competente. (Artigo acrescido pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l8958:4","law":"l8958","ref":"4","label":"Lei 8.958/1994 · Art. 4","paragraphs":["Art. 4º. As IFES e demais ICTs contratantes poderão autorizar, de acordo com as normas aprovadas pelo órgão de direção superior competente e limites e condições previstos em regulamento, a participação de seus servidores nas atividades realizadas pelas fundações referidas no art. 1º desta Lei, sem prejuízo de suas atribuições funcionais. (“Caput” do artigo com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 1º A participação de servidores das IFES e demais ICTs contratantes nas atividades previstas no art. 1º desta Lei, autorizada nos termos deste artigo, não cria vínculo empregatício de qualquer natureza, podendo as fundações contratadas, para sua execução, conceder bolsas de ensino, de pesquisa e de extensão, de acordo com os parâmetros a serem fixados em regulamento. (Parágrafo com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 2º É vedada aos servidores públicos federais a participação nas atividades referidas no caput durante a jornada de trabalho a que estão sujeitos, excetuada a colaboração esporádica, remunerada ou não, em assuntos de sua especialidade, de acordo com as normas referidas no caput.","§ 3º É vedada a utilização dos contratados referidos no caput para contratação de pessoal administrativo, de manutenção, docentes ou pesquisadores para prestar serviços ou atender a necessidades de caráter permanente das contratantes. (Parágrafo com redação dada pela Lei nº 12.349, de 15/12/2010)","§ 4º Os servidores ocupantes de cargo em comissão ou função de confiança nas IFES demais ICTs poderão desenvolver atividades de ensino, pesquisa e extensão no âmbito dos projetos apoiados pelas fundações de apoio com recebimento de bolsas. (Parágrafo acrescido pela Lei nº 12.863, de 24/9/2013)","§ 5º É permitida a participação não remunerada de servidores das IFES e demais ICTs nos órgãos de direção de Fundações de Apoio, não lhes sendo aplicável o disposto no inciso X do caput do art. 117 da Lei nº 8.112, de 11 de dezembro de 1990. (Parágrafo acrescido pela Lei nº 12.863, de 24/9/2013)","§ 6º Não se aplica o disposto no § 5º aos servidores das IFES e demais ICTs investidos em cargo em comissão ou função de confiança. (Parágrafo acrescido pela Lei nº 12.863, de 24/9/2013)","§ 7º Os servidores das IFES e demais ICTs somente poderão participar de atividades nas fundações de apoio quando não houver prejuízo ao cumprimento de sua jornada de trabalho na entidade de origem, ressalvada a hipótese de cessão especial prevista no inciso II do § 4º do art. 20 da Lei nº 12.772, de 28 de dezembro de 2012. (Parágrafo acrescido pela Lei nº 12.863, de 24/9/2013)","§ 8º (VETADO na Lei nº 13.243, de 11/1/2016)"],"url":""},{"key":"l8958:4-A","law":"l8958","ref":"4-A","label":"Lei 8.958/1994 · Art. 4-A","paragraphs":["Art. 4º-A Serão divulgados, na íntegra, em sítio mantido pela fundação de apoio na rede mundial de computadores - internet: (“Caput” do artigo acrescido pela Medida Provisória nº 495, de 19/7/2010, convertida na Lei nº 12.349, de 15/12/2010)","I - os instrumentos contratuais de que trata esta Lei, firmados e mantidos pela fundação de apoio com as IFES e demais ICTs, bem como com a FINEP, o CNPq e as Agências Financeiras Oficiais de Fomento; (Inciso acrescido pela Medida Provisória nº 495, de 19/7/2010, com redação dada pela Lei nº 12.349, de 15/12/2010)","II - os relatórios semestrais de execução dos contratos de que trata o inciso I, indicando os valores executados, as atividades, as obras e os serviços realizados, discriminados por projeto, unidade acadêmica ou pesquisa beneficiária; (Inciso acrescido pela Medida Provisória nº 495, de 19/7/2010, convertida na Lei nº 12.349, de 15/12/2010)","III - a relação dos pagamentos efetuados a servidores ou agentes públicos de qualquer natureza em decorrência dos contratos de que trata o inciso I; (Inciso acrescido pela Medida Provisória nº 495, de 19/7/2010, convertida na Lei nº 12.349, de 15/12/2010)","IV - a relação dos pagamentos de qualquer natureza efetuados a pessoas físicas e jurídicas em decorrência dos contratos de que trata o inciso I; e (Inciso acrescido pela Lei nº 12.349, de 15/12/2010)","V - as prestações de contas dos instrumentos contratuais de que trata esta Lei, firmados e mantidos pela fundação de apoio com as IFES e demais ICTs, bem como com a FINEP, o CNPq e as Agências Financeiras Oficiais de Fomento. (Inciso acrescido pela Lei nº 12.349, de 15/12/2010)"],"url":""},{"key":"l8958:4-B","law":"l8958","ref":"4-B","label":"Lei 8.958/1994 · Art. 4-B","paragraphs":["Art. 4º -B. As fundações de apoio poderão conceder bolsas de ensino, pesquisa e extensão e de estímulo à inovação aos estudantes de cursos técnicos, de graduação e pós-graduação e aos servidores vinculados a projetos institucionais, inclusive em rede, das IFES e demais ICTs apoiadas, na forma da regulamentação específica, observados os princípios referidos no art. 2º. (Artigo acrescido pela Medida Provisória nº 495, de 19/7/2010, convertida na Lei nº 12.349, de 15/12/2010, com redação dada pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l8958:4-C","law":"l8958","ref":"4-C","label":"Lei 8.958/1994 · Art. 4-C","paragraphs":["Art. 4º -C. É assegurado o acesso dos órgãos e das entidades públicas concedentes ou contratantes e do Sistema de Controle Interno do Poder Executivo federal aos processos, aos documentos e às informações referentes aos recursos públicos recebidos pelas fundações de apoio enquadradas na situação prevista no art. 1º e aos locais de execução do objeto do contrato ou convênio. (Artigo acrescido pela Lei nº 12.349, de 15/12/2010, com redação dada pela Lei nº 12.863, de 24/9/2013)"],"url":""},{"key":"l11107:3","law":"l11107","ref":"3","label":"Lei 11.107/2005 · Art. 3","paragraphs":["Art. 3º O consórcio público será constituído por contrato cuja celebração dependerá da prévia subscrição de protocolo de intenções."],"url":""},{"key":"l11107:4","law":"l11107","ref":"4","label":"Lei 11.107/2005 · Art. 4","paragraphs":["Art. 4º São cláusulas necessárias do protocolo de intenções as que estabeleçam:","I - a denominação, a finalidade, o prazo de duração e a sede do consórcio;","II - a identificação dos entes da Federação consorciados;","III - a indicação da área de atuação do consórcio;","IV - a previsão de que o consórcio público é associação pública ou pessoa jurídica de direito privado sem fins econômicos;","V - os critérios para, em assuntos de interesse comum, autorizar o consórcio público a representar os entes da Federação consorciados perante outras esferas de governo;","VI - as normas de convocação e funcionamento da assembléia geral, inclusive para a elaboração, aprovação e modificação dos estatutos do consórcio público;","VII - a previsão de que a assembléia geral é a instância máxima do consórcio público e o número de votos para as suas deliberações;","VIII - a forma de eleição e a duração do mandato do representante legal do consórcio público que, obrigatoriamente, deverá ser Chefe do Poder Executivo de ente da Federação consorciado;","IX - o número, as formas de provimento e a remuneração dos empregados públicos, bem como os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","X - as condições para que o consórcio público celebre contrato de gestão ou termo de parceria;","XI - a autorização para a gestão associada de serviços públicos, explicitando:","a) as competências cujo exercício se transferiu ao consórcio público;","b) os serviços públicos objeto da gestão associada e a área em que serão prestados;","c) a autorização para licitar ou outorgar concessão, permissão ou autorização da prestação dos serviços;","d) as condições a que deve obedecer o contrato de programa, no caso de a gestão associada envolver também a prestação de serviços por órgão ou entidade de um dos entes da Federação consorciados;","e) os critérios técnicos para cálculo do valor das tarifas e de outros preços públicos, bem como para seu reajuste ou revisão; e","XII - o direito de qualquer dos contratantes, quando adimplente com suas obrigações, de exigir o pleno cumprimento das cláusulas do contrato de consórcio público.","§ 1º Para os fins do inciso III do caput deste artigo, considera- se como área de atuação do consórcio público, independentemente de figurar a União como consorciada, a que corresponde à soma dos territórios:","I - dos Municípios, quando o consórcio público for constituído somente por Municípios ou por um Estado e Municípios com territórios nele contidos;","II - dos Estados ou dos Estados e do Distrito Federal, quando o consórcio público for, respectivamente, constituído por mais de 1 (um) Estado ou por 1 (um) ou mais Estados e o Distrito Federal;","III - (VETADO)","IV - dos Municípios e do Distrito Federal, quando o consórcio for constituído pelo Distrito Federal e os Municípios; e","V - (VETADO)","§ 2º O protocolo de intenções deve definir o número de votos que cada ente da Federação consorciado possui na assembléia geral, sendo assegurado 1 (um) voto a cada ente consorciado.","§ 3º É nula a cláusula do contrato de consórcio que preveja determinadas contribuições financeiras ou econômicas de ente da Federação ao consórcio público, salvo a doação, destinação ou cessão do uso de bens móveis ou imóveis e as transferências ou cessões de direitos operadas por força de gestão associada de serviços públicos.","§ 4º Os entes da Federação consorciados, ou os com eles conveniados, poderão ceder-lhe servidores, na forma e condições da legislação de cada um.","§ 5º O protocolo de intenções deverá ser publicado na imprensa oficial."],"url":""},{"key":"l11107:5","law":"l11107","ref":"5","label":"Lei 11.107/2005 · Art. 5","paragraphs":["Art. 5º O contrato de consórcio público será celebrado com a ratificação, mediante lei, do protocolo de intenções.","§ 1º O contrato de consórcio público, caso assim preveja cláusula, pode ser celebrado por apenas 1 (uma) parcela dos entes da Federação que subscreveram o protocolo de intenções.","§ 2º A ratificação pode ser realizada com reserva que, aceita pelos demais entes subscritores, implicará consorciamento parcial ou condicional.","§ 3º A ratificação realizada após 2 (dois) anos da subscrição do protocolo de intenções dependerá de homologação da assembléia geral do consórcio público.","§ 4º É dispensado da ratificação prevista no caput deste artigo o ente da Federação que, antes de subscrever o protocolo de intenções, disciplinar por lei a sua participação no consórcio público."],"url":""},{"key":"l11107:7","law":"l11107","ref":"7","label":"Lei 11.107/2005 · Art. 7","paragraphs":["Art. 7º Os estatutos disporão sobre a organização e o funcionamento de cada um dos órgãos constitutivos do consórcio público."],"url":""},{"key":"l11107:10","law":"l11107","ref":"10","label":"Lei 11.107/2005 · Art. 10","paragraphs":["Art. 10. (VETADO)","Parágrafo único. Os agentes públicos incumbidos da gestão de consórcio não responderão pessoalmente pelas obrigações contraídas pelo consórcio público, mas responderão pelos atos praticados em desconformidade com a lei ou com as disposições dos respectivos estatutos."],"url":""},{"key":"l11107:8","law":"l11107","ref":"8","label":"Lei 11.107/2005 · Art. 8","paragraphs":["Art. 8º Os entes consorciados somente entregarão recursos ao consórcio público mediante contrato de rateio.","§ 1º O contrato de rateio será formalizado em cada exercício financeiro, e seu prazo de vigência não será superior ao das dotações que o suportam, com exceção dos contratos que tenham por objeto exclusivamente projetos consistentes em programas e ações contemplados em plano plurianual. (Parágrafo com redação dada pela Lei nº 14.026, de 15/7/2020)","§ 2º É vedada a aplicação dos recursos entregues por meio de contrato de rateio para o atendimento de despesas genéricas, inclusive transferências ou operações de crédito.","§ 3º Os entes consorciados, isolados ou em conjunto, bem como o consórcio público, são partes legítimas para exigir o cumprimento das obrigações previstas no contrato de rateio.","§ 4º Com o objetivo de permitir o atendimento dos dispositivos da Lei Complementar nº 101, de 4 de maio de 2000, o consórcio público deve fornecer as informações necessárias para que sejam consolidadas, nas contas dos entes consorciados, todas as despesas realizadas com os recursos entregues em virtude de contrato de rateio, de forma que possam ser contabilizadas nas contas de cada ente da Federação na conformidade dos elementos econômicos e das atividades ou projetos atendidos.","§ 5º Poderá ser excluído do consórcio público, após prévia suspensão, o ente consorciado que não consignar, em sua lei orçamentária ou em créditos adicionais, as dotações suficientes para suportar as despesas assumidas por meio de contrato de rateio."],"url":""},{"key":"l11107:9","law":"l11107","ref":"9","label":"Lei 11.107/2005 · Art. 9","paragraphs":["Art. 9º A execução das receitas e despesas do consórcio público deverá obedecer às normas de direito financeiro aplicáveis às entidades públicas.","Parágrafo único. O consórcio público está sujeito à fiscalização contábil, operacional e patrimonial pelo Tribunal de Contas competente para apreciar as contas do Chefe do Poder Executivo representante legal do consórcio, inclusive quanto à legalidade, legitimidade e economicidade das despesas, atos, contratos e renúncia de receitas, sem prejuízo do controle externo a ser exercido em razão de cada um dos contratos de rateio."],"url":""},{"key":"l11107:11","law":"l11107","ref":"11","label":"Lei 11.107/2005 · Art. 11","paragraphs":["Art. 11. A retirada do ente da Federação do consórcio público dependerá de ato formal de seu representante na assembléia geral, na forma previamente disciplinada por lei.","§ 1º Os bens destinados ao consórcio público pelo consorciado que se retira somente serão revertidos ou retrocedidos no caso de expressa previsão no contrato de consórcio público ou no instrumento de transferência ou de alienação.","§ 2º A retirada ou a extinção de consórcio público ou convênio de cooperação não prejudicará as obrigações já constituídas, inclusive os contratos, cuja extinção dependerá do pagamento das indenizações eventualmente devidas. (Parágrafo com redação dada pela Lei nº 14.026, de 15/7/2020)"],"url":""},{"key":"l11107:13","law":"l11107","ref":"13","label":"Lei 11.107/2005 · Art. 13","paragraphs":["Art. 13. Deverão ser constituídas e reguladas por contrato de programa, como condição de sua validade, as obrigações que um ente da Federação constituir para com outro ente da Federação ou para com consórcio público no âmbito de gestão associada em que haja a prestação de serviços públicos ou a transferência total ou parcial de encargos, serviços, pessoal ou de bens necessários à continuidade dos serviços transferidos.","§ 1º O contrato de programa deverá:","I - atender à legislação de concessões e permissões de serviços públicos e, especialmente no que se refere ao cálculo de tarifas e de outros preços públicos, à de regulação dos serviços a serem prestados; e","II - prever procedimentos que garantam a transparência da gestão econômica e financeira de cada serviço em relação a cada um de seus titulares.","§ 2º No caso de a gestão associada originar a transferência total ou parcial de encargos, serviços, pessoal e bens essenciais à continuidade dos serviços transferidos, o contrato de programa, sob pena de nulidade, deverá conter cláusulas que estabeleçam:","I - os encargos transferidos e a responsabilidade subsidiária da entidade que os transferiu;","II - as penalidades no caso de inadimplência em relação aos encargos transferidos;","III - o momento de transferência dos serviços e os deveres relativos a sua continuidade;","IV - a indicação de quem arcará com o ônus e os passivos do pessoal transferido;","V - a identificação dos bens que terão apenas a sua gestão e administração transferidas e o preço dos que sejam efetivamente alienados ao contratado;","VI - o procedimento para o levantamento, cadastro e avaliação dos bens reversíveis que vierem a ser amortizados mediante receitas de tarifas ou outras emergentes da prestação dos serviços.","§ 3º É nula a cláusula de contrato de programa que atribuir ao contratado o exercício dos poderes de planejamento, regulação e fiscalização dos serviços por ele próprio prestados.","§ 4º O contrato de programa continuará vigente mesmo quando extinto o consórcio público ou o convênio de cooperação que autorizou a gestão associada de serviços públicos.","§ 5º Mediante previsão do contrato de consórcio público, ou de convênio de cooperação, o contrato de programa poderá ser celebrado por entidades de direito público ou privado que integrem a administração indireta de qualquer dos entes da Federação consorciados ou conveniados.","§ 6º (Revogado pela Lei nº 14.026, de 15/7/2020)","§ 7º Excluem-se do previsto no caput deste artigo as obrigações cujo descumprimento não acarrete qualquer ônus, inclusive financeiro, a ente da Federação ou a consórcio público.","§ 8º Os contratos de prestação de serviços públicos de saneamento básico deverão observar o art. 175 da Constituição Federal, vedada a formalização de novos contratos de programa para esse fim. (Parágrafo acrescido pela Lei nº 14.026, de 15/7/2020)"],"url":""},{"key":"l11107:14","law":"l11107","ref":"14","label":"Lei 11.107/2005 · Art. 14","paragraphs":["Art. 14. A União poderá celebrar convênios com os consórcios públicos, com o objetivo de viabilizar a descentralização e a prestação de políticas públicas em escalas adequadas.","Parágrafo único. Para a celebração dos convênios de que trata o caput deste artigo, as exigências legais de regularidade aplicar-se-ão ao próprio consórcio público envolvido, e não aos entes federativos nele consorciados. (Parágrafo único acrescido pela Lei nº 13.821, de 3/5/2019)"],"url":""},{"key":"d6017:3","law":"d6017","ref":"3","label":"Decreto 6.017/2007 · Art. 3","paragraphs":["Art. 3º Observados os limites constitucionais e legais, os objetivos dos consórcios públicos serão determinados pelos entes que se consorciarem, admitindo-se, entre outros, os seguintes:","I - a gestão associada de serviços públicos;","II - a prestação de serviços, inclusive de assistência técnica, a execução de obras e o fornecimento de bens à administração direta ou indireta dos entes consorciados;","III - o compartilhamento ou o uso em comum de instrumentos e equipamentos, inclusive de gestão, de manutenção, de informática, de pessoal técnico e de procedimentos de licitação e de admissão de pessoal;","IV - a produção de informações ou de estudos técnicos;","V - a instituição e o funcionamento de escolas de governo ou de estabelecimentos congêneres;","VI - a promoção do uso racional dos recursos naturais e a proteção do meio-ambiente;","VII - o exercício de funções no sistema de gerenciamento de recursos hídricos que lhe tenham sido delegadas ou autorizadas;","VIII - o apoio e o fomento do intercâmbio de experiências e de informações entre os entes consorciados;","IX - a gestão e a proteção de patrimônio urbanístico, paisagístico ou turístico comum;","X - o planejamento, a gestão e a administração dos serviços e recursos da previdência social dos servidores de qualquer dos entes da Federação que integram o consórcio, vedado que os recursos arrecadados em um ente federativo sejam utilizados no pagamento de benefícios de segurados de outro ente, de forma a atender o disposto no art. 1o, inciso V, da Lei nº 9.717, de 1998;","XI - o fornecimento de assistência técnica, extensão, treinamento, pesquisa e desenvolvimento urbano, rural e agrário;","XII - as ações e políticas de desenvolvimento urbano, sócio-econômico local e regional; e","XIII - o exercício de competências pertencentes aos entes da Federação nos termos de autorização ou delegação.","§ 1º Os consórcios públicos poderão ter um ou mais objetivos e os entes consorciados poderão se consorciar em relação a todos ou apenas a parcela deles.","§ 2º Os consórcios públicos, ou entidade a ele vinculada, poderão desenvolver as ações e os serviços de saúde, obedecidos os princípios, diretrizes e normas que regulam o Sistema Único de Saúde - SUS."],"url":""},{"key":"d6017:9","law":"d6017","ref":"9","label":"Decreto 6.017/2007 · Art. 9","paragraphs":["Art. 9º Os entes da Federação consorciados respondem subsidiariamente pelas obrigações do consórcio público.","Parágrafo único. Os dirigentes do consórcio público responderão pessoalmente pelas obrigações por ele contraídas caso pratiquem atos em desconformidade com a lei, os estatutos ou decisão da assembléia geral."],"url":""},{"key":"d6017:4","law":"d6017","ref":"4","label":"Decreto 6.017/2007 · Art. 4","paragraphs":["Art. 4º A constituição de consórcio público dependerá da prévia celebração de protocolo de intenções subscrito pelos representantes legais dos entes da Federação interessados."],"url":""},{"key":"d6017:5","law":"d6017","ref":"5","label":"Decreto 6.017/2007 · Art. 5","paragraphs":["Art. 5º O protocolo de intenções, sob pena de nulidade, deverá conter, no mínimo, cláusulas que estabeleçam:","I - a denominação, as finalidades, o prazo de duração e a sede do consórcio público, admitindo-se a fixação de prazo indeterminado e a previsão de alteração da sede mediante decisão da Assembléia Geral;","II - a identificação de cada um dos entes da Federação que podem vir a integrar o consórcio público, podendo indicar prazo para que subscrevam o protocolo de intenções;","III - a indicação da área de atuação do consórcio público;","IV - a previsão de que o consórcio público é associação pública, com personalidade jurídica de direito público e natureza autárquica, ou pessoa jurídica de direito privado;","V - os critérios para, em assuntos de interesse comum, autorizar o consórcio público a representar os entes da Federação consorciados perante outras esferas de governo;","VI - as normas de convocação e funcionamento da assembléia geral, inclusive para a elaboração, aprovação e modificação dos estatutos do consórcio público;","VII - a previsão de que a assembléia geral é a instância máxima do consórcio público e o número de votos para as suas deliberações;","VIII - a forma de eleição e a duração do mandato do representante legal do consórcio público que, obrigatoriamente, deverá ser Chefe do Poder Executivo de ente da Federação consorciado;","IX - o número, as formas de provimento e a remuneração dos empregados do consórcio público;","X - os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","XI - as condições para que o consórcio público celebre contrato de gestão, nos termos da Lei nº 9.649, de 1998, ou termo de parceria, na forma da Lei nº 9.790, de 1999;","XII - a autorização para a gestão associada de serviço público, explicitando:","a) competências cuja execução será transferida ao consórcio público;","b) os serviços públicos objeto da gestão associada e a área em que serão prestados;","c) a autorização para licitar e contratar concessão, permissão ou autorizar a prestação dos serviços;","d) as condições a que deve obedecer o contrato de programa, no caso de nele figurar como contratante o consórcio público; e","e) os critérios técnicos de cálculo do valor das tarifas e de outros preços públicos, bem como os critérios gerais a serem observados em seu reajuste ou revisão;","XIII - o direito de qualquer dos contratantes, quando adimplentes com as suas obrigações, de exigir o pleno cumprimento das cláusulas do contrato de consórcio público.","§ 1º O protocolo de intenções deve definir o número de votos que cada ente da Federação consorciado possui na assembléia geral, sendo assegurado a cada um ao menos um voto.","§ 2º Admitir-se-á, à exceção da assembléia geral:","I - a participação de representantes da sociedade civil nos órgãos colegiados do consórcio público;","II - que órgãos colegiados do consórcio público sejam compostos por representantes da sociedade civil ou por representantes apenas dos entes consorciados diretamente interessados nas matérias de competência de tais órgãos.","§ 3º Os consórcios públicos deverão obedecer ao princípio da publicidade, tornando públicas as decisões que digam respeito a terceiros e as de natureza orçamentária, financeira ou contratual, inclusive as que digam respeito à admissão de pessoal, bem como permitindo que qualquer do povo tenha acesso a suas reuniões e aos documentos que produzir, salvo, nos termos da lei, os considerados sigilosos por prévia e motivada decisão.","§ 4º O mandato do representante legal do consórcio público será fixado em um ou mais exercícios financeiros e cessará automaticamente no caso de o eleito não mais ocupar a Chefia do Poder Executivo do ente da Federação que representa na assembléia geral, hipótese em que será sucedido por quem preencha essa condição.","§ 5º Salvo previsão em contrário dos estatutos, o representante legal do consórcio público, nos seus impedimentos ou na vacância, será substituído ou sucedido por aquele que, nas mesmas hipóteses, o substituir ou o suceder na Chefia do Poder Executivo.","§ 6º É nula a cláusula do protocolo de intenções que preveja determinadas contribuições financeiras ou econômicas de ente da Federação ao consórcio público, salvo a doação, destinação ou cessão do uso de bens móveis ou imóveis e as transferências ou cessões de direitos operadas por força de gestão associada de serviços públicos.","§ 7º O protocolo de intenções deverá ser publicado na imprensa oficial.","§ 8º A publicação do protocolo de intenções poderá dar-se de forma resumida, desde que a publicação indique o local e o sítio da rede mundial de computadores - internet em que se poderá obter seu texto integral."],"url":""},{"key":"d6017:6","law":"d6017","ref":"6","label":"Decreto 6.017/2007 · Art. 6","paragraphs":["Art. 6º O contrato de consórcio público será celebrado com a ratificação, mediante lei, do protocolo de intenções.","§ 1º A recusa ou demora na ratificação não poderá ser penalizada.","§ 2º A ratificação pode ser realizada com reserva que deverá ser clara e objetiva, preferencialmente vinculada à vigência de cláusula, parágrafo, inciso ou alínea do protocolo de intenções, ou que imponha condições para a vigência de qualquer desses dispositivos.","§ 3º Caso a lei mencionada no caput deste artigo preveja reservas, a admissão do ente no consórcio público dependerá da aprovação de cada uma das reservas pelos demais subscritores do protocolo de intenções ou, caso já constituído o consórcio público, pela assembléia geral.","§ 4º O contrato de consórcio público, caso assim esteja previsto no protocolo de intenções, poderá ser celebrado por apenas uma parcela dos seus signatários, sem prejuízo de que os demais venham a integrá-lo posteriormente.","§ 5º No caso previsto no § 4º deste artigo, a ratificação realizada após dois anos da primeira subscrição do protocolo de intenções dependerá da homologação dos demais subscritores ou, caso já constituído o consórcio, de decisão da assembléia geral.","§ 6º Dependerá de alteração do contrato de consórcio público o ingresso de ente da Federação não mencionado no protocolo de intenções como possível integrante do consórcio público.","§ 7º É dispensável a ratificação prevista no caput deste artigo para o ente da Federação que, antes de subscrever o protocolo de intenções, disciplinar por lei a sua participação no consórcio público, de forma a poder assumir todas as obrigações previstas no protocolo de intenções."],"url":""},{"key":"d6017:7","law":"d6017","ref":"7","label":"Decreto 6.017/2007 · Art. 7","paragraphs":["Art. 7º O consórcio público adquirirá personalidade jurídica:","I - de direito público, mediante a vigência das leis de ratificação do protocolo de intenções; e","II - de direito privado, mediante o atendimento do previsto no inciso I e, ainda, dos requisitos previstos na legislação civil.","§ 1º Os consórcios públicos, ainda que revestidos de personalidade jurídica de direito privado, observarão as normas de direito público no que concerne à realização de licitação, celebração de contratos, admissão de pessoal e à prestação de contas.","§ 2º Caso todos os subscritores do protocolo de intenções encontrem-se na situação prevista no § 7º do art. 6º deste Decreto, o aperfeiçoamento do contrato de consórcio público e a aquisição da personalidade jurídica pela associação pública dependerão apenas da publicação do protocolo de intenções.","§ 3º Nas hipóteses de criação, fusão, incorporação ou desmembramento que atinjam entes consorciados ou subscritores de protocolo de intenções, os novos entes da Federação, salvo disposição em contrário do protocolo de intenções, serão automaticamente tidos como consorciados ou subscritores."],"url":""},{"key":"d6017:8","law":"d6017","ref":"8","label":"Decreto 6.017/2007 · Art. 8","paragraphs":["Art. 8º O consórcio público será organizado por estatutos cujas disposições, sob pena de nulidade, deverão atender a todas as cláusulas do seu contrato constitutivo.","§ 1º Os estatutos serão aprovados pela assembléia geral.","§ 2º Com relação aos empregados públicos do consórcio público, os estatutos poderão dispor sobre o exercício do poder disciplinar e regulamentar, as atribuições administrativas, hierarquia, avaliação de eficiência, lotação, jornada de trabalho e denominação dos cargos.","§ 3º Os estatutos do consórcio público de direito público produzirão seus efeitos mediante publicação na imprensa oficial no âmbito de cada ente consorciado.","§ 4º A publicação dos estatutos poderá dar-se de forma resumida, desde que a publicação indique o local e o sítio da rede mundial de computadores - internet em que se poderá obter seu texto integral."],"url":""},{"key":"d6017:10","law":"d6017","ref":"10","label":"Decreto 6.017/2007 · Art. 10","paragraphs":["Art. 10. Para cumprimento de suas finalidades, o consórcio público poderá:","I - firmar convênios, contratos, acordos de qualquer natureza, receber auxílios, contribuições e subvenções sociais ou econômicas;","II - ser contratado pela administração direta ou indireta dos entes da Federação consorciados, dispensada a licitação; e","III - caso constituído sob a forma de associação pública, ou mediante previsão em contrato de programa, promover desapropriações ou instituir servidões nos termos de declaração de utilidade ou necessidade pública, ou de interesse social.","Parágrafo único. A contratação de operação de crédito por parte do consórcio público se sujeita aos limites e condições próprios estabelecidos pelo Senado Federal, de acordo com o disposto no art. 52, inciso VII, da Constituição."],"url":""},{"key":"d6017:18","law":"d6017","ref":"18","label":"Decreto 6.017/2007 · Art. 18","paragraphs":["Art. 18. O consórcio público poderá ser contratado por ente consorciado, ou por entidade que integra a administração indireta deste último, sendo dispensada a licitação nos termos do art. 2º, inciso III, da Lei nº 11.107, de 2005.","Parágrafo único. O contrato previsto no caput, preferencialmente, deverá ser celebrado sempre quando o consórcio fornecer bens ou prestar serviços para um determinado ente consorciado, de forma a impedir que sejam eles custeados pelos demais."],"url":""},{"key":"d6017:11","law":"d6017","ref":"11","label":"Decreto 6.017/2007 · Art. 11","paragraphs":["Art. 11. A execução das receitas e das despesas do consórcio público deverá obedecer às normas de direito financeiro aplicáveis às entidades públicas."],"url":""},{"key":"d6017:12","law":"d6017","ref":"12","label":"Decreto 6.017/2007 · Art. 12","paragraphs":["Art. 12. O consórcio público está sujeito à fiscalização contábil, operacional e patrimonial pelo Tribunal de Contas competente para apreciar as contas do seu representante legal, inclusive quanto à legalidade, legitimidade e economicidade das despesas, atos, contratos e renúncia de receitas, sem prejuízo do controle externo a ser exercido em razão de cada um dos contratos que os entes da Federação consorciados vierem a celebrar com o consórcio público."],"url":""},{"key":"d6017:13","law":"d6017","ref":"13","label":"Decreto 6.017/2007 · Art. 13","paragraphs":["Art. 13. Os entes consorciados somente entregarão recursos financeiros ao consórcio público mediante contrato de rateio.","§ 1º O contrato de rateio será formalizado em cada exercício financeiro, com observância da legislação orçamentária e financeira do ente consorciado contratante e depende da previsão de recursos orçamentários que suportem o pagamento das obrigações contratadas.","§ 2º Constitui ato de improbidade administrativa, nos termos do disposto no art. 10, inciso XV, da Lei nº 8.429, de 2 de junho de 1992, celebrar contrato de rateio sem suficiente e prévia dotação orçamentária, ou sem observar as formalidades previstas em Lei.","§ 3º As cláusulas do contrato de rateio não poderão conter disposição tendente a afastar, ou dificultar a fiscalização exercida pelos órgãos de controle interno e externo ou pela sociedade civil de qualquer dos entes da Federação consorciados.","§ 4º Os entes consorciados, isolados ou em conjunto, bem como o consórcio público, são partes legítimas para exigir o cumprimento das obrigações previstas no contrato de rateio."],"url":""},{"key":"d6017:14","law":"d6017","ref":"14","label":"Decreto 6.017/2007 · Art. 14","paragraphs":["Art. 14. Havendo restrição na realização de despesas, de empenhos ou de movimentação financeira, ou qualquer outra derivada das normas de direito financeiro, o ente consorciado, mediante notificação escrita, deverá informá-la ao consórcio público, apontando as medidas que tomou para regularizar a situação, de modo a garantir a contribuição prevista no contrato de rateio.","Parágrafo único. A eventual impossibilidade de o ente consorciado cumprir obrigação orçamentária e financeira estabelecida em contrato de rateio obriga o consórcio público a adotar medidas para adaptar a execução orçamentária e financeira aos novos limites."],"url":""},{"key":"d6017:15","law":"d6017","ref":"15","label":"Decreto 6.017/2007 · Art. 15","paragraphs":["Art. 15. É vedada a aplicação dos recursos entregues por meio de contrato de rateio, inclusive os oriundos de transferências ou operações de crédito, para o atendimento de despesas classificadas como genéricas.","§ 1º Entende-se por despesa genérica aquela em que a execução orçamentária se faz com modalidade de aplicação indefinida.","§ 2º Não se considera como genérica as despesas de administração e planejamento, desde que previamente classificadas por meio de aplicação das normas de contabilidade pública."],"url":""},{"key":"d6017:16","law":"d6017","ref":"16","label":"Decreto 6.017/2007 · Art. 16","paragraphs":["Art. 16. O prazo de vigência do contrato de rateio não será superior ao de vigência das dotações que o suportam, com exceção dos que tenham por objeto exclusivamente projetos consistentes em programas e ações contemplados em plano plurianual."],"url":""},{"key":"d6017:17","law":"d6017","ref":"17","label":"Decreto 6.017/2007 · Art. 17","paragraphs":["Art. 17. Com o objetivo de permitir o atendimento dos dispositivos da Lei Complementar nº 101, de 4 de maio de 2000, o consórcio público deve fornecer as informações financeiras necessárias para que sejam consolidadas, nas contas dos entes consorciados, todas as receitas e despesas realizadas, de forma a que possam ser contabilizadas nas contas de cada ente da Federação na conformidade dos elementos econômicos e das atividades ou projetos atendidos."],"url":""},{"key":"d6017:22","law":"d6017","ref":"22","label":"Decreto 6.017/2007 · Art. 22","paragraphs":["Art. 22. A criação de empregos públicos depende de previsão do contrato de consórcio público que lhe fixe a forma e os requisitos de provimento e a sua respectiva remuneração, inclusive quanto aos adicionais, gratificações, e quaisquer outras parcelas remuneratórias ou de caráter indenizatório."],"url":""},{"key":"d6017:23","law":"d6017","ref":"23","label":"Decreto 6.017/2007 · Art. 23","paragraphs":["Art. 23. Os entes da Federação consorciados, ou os com eles conveniados, poderão ceder-lhe servidores, na forma e condições da legislação de cada um.","§ 1º Os servidores cedidos permanecerão no seu regime originário, somente lhe sendo concedidos adicionais ou gratificações nos termos e valores previstos no contrato de consórcio público.","§ 2º O pagamento de adicionais ou gratificações na forma prevista no § 1º deste artigo não configura vínculo novo do servidor cedido, inclusive para a apuração de responsabilidade trabalhista ou previdenciária.","§ 3º Na hipótese de o ente da Federação consorciado assumir o ônus da cessão do servidor, tais pagamentos poderão ser contabilizados como créditos hábeis para operar compensação com obrigações previstas no contrato de rateio."],"url":""},{"key":"d6017:24","law":"d6017","ref":"24","label":"Decreto 6.017/2007 · Art. 24","paragraphs":["Art. 24. Nenhum ente da Federação poderá ser obrigado a se consorciar ou a permanecer consorciado."],"url":""},{"key":"d6017:25","law":"d6017","ref":"25","label":"Decreto 6.017/2007 · Art. 25","paragraphs":["Art. 25. A retirada do ente da Federação do consórcio público dependerá de ato formal de seu representante na assembléia geral, na forma previamente disciplinada por lei.","§ 1º Os bens destinados ao consórcio público pelo consorciado que se retira somente serão revertidos ou retrocedidos no caso de expressa previsão do contrato de consórcio público ou do instrumento de transferência ou de alienação.","§ 2º A retirada não prejudicará as obrigações já constituídas entre o consorciado que se retira e o consórcio público.","§ 3º A retirada de um ente da Federação do consórcio público constituído por apenas dois entes implicará a extinção do consórcio."],"url":""},{"key":"d6017:26","law":"d6017","ref":"26","label":"Decreto 6.017/2007 · Art. 26","paragraphs":["Art. 26. A exclusão de ente consorciado só é admissível havendo justa causa.","§ 1º Além das que sejam reconhecidas em procedimento específico, é justa causa a não inclusão, pelo ente consorciado, em sua lei orçamentária ou em créditos adicionais, de dotações suficientes para suportar as despesas que, nos termos do orçamento do consórcio público, prevê-se devam ser assumidas por meio de contrato de rateio.","§ 2º A exclusão prevista no § 1º deste artigo somente ocorrerá após prévia suspensão, período em que o ente consorciado poderá se reabilitar."],"url":""},{"key":"d6017:27","law":"d6017","ref":"27","label":"Decreto 6.017/2007 · Art. 27","paragraphs":["Art. 27. A exclusão de consorciado exige processo administrativo onde lhe seja assegurado o direito à ampla defesa e ao contraditório."],"url":""},{"key":"d6017:28","law":"d6017","ref":"28","label":"Decreto 6.017/2007 · Art. 28","paragraphs":["Art. 28. Mediante previsão do contrato de consórcio público, poderá ser dele excluído o ente que, sem autorização dos demais consorciados, subscrever protocolo de intenções para constituição de outro consórcio com finalidades, a juízo da maioria da assembléia geral, iguais, assemelhadas ou incompatíveis."],"url":""},{"key":"d6017:30","law":"d6017","ref":"30","label":"Decreto 6.017/2007 · Art. 30","paragraphs":["Art. 30. Deverão ser constituídas e reguladas por contrato de programa, como condição de sua validade, as obrigações contraídas por ente da Federação, inclusive entidades de sua administração indireta, que tenham por objeto a prestação de serviços por meio de gestão associada ou a transferência total ou parcial de encargos, serviços, pessoal ou de bens necessários à continuidade dos serviços transferidos.","§ 1º Para os fins deste artigo, considera-se prestação de serviço público por meio de gestão associada aquela em que um ente da Federação, ou entidade de sua administração indireta, coopere com outro ente da Federação ou com consórcio público, independentemente da denominação que venha a adotar, exceto quando a prestação se der por meio de contrato de concessão de serviços públicos celebrado após regular licitação.","§ 2º Constitui ato de improbidade administrativa, a partir de 7 de abril de 2005, celebrar contrato ou outro instrumento que tenha por objeto a prestação de serviços públicos por meio de cooperação federativa sem a celebração de contrato de programa, ou sem que sejam observadas outras formalidades previstas em lei, nos termos do disposto no art. 10, inciso XIV, da Lei nº 8.429, de 1992.","§ 3º Excluem-se do previsto neste artigo as obrigações cujo descumprimento não acarrete qualquer ônus, inclusive financeiro, a ente da Federação ou a consórcio público."],"url":""}];})(window);
